// CUN ATTEND - single-file project bundle.
// Run "node bootstrap.js" to recreate the entire project in this folder.
// Render build command:  node bootstrap.js && npm install --include=dev && npm run build
// Render start command:  npm start
const fs = require('fs'), path = require('path');
const files = {
 ".env.example": "NODE_ENV=development\nPORT=3000\nTELEGRAM_BOT_TOKEN=\nDATABASE_URL=postgres://postgres:postgres@localhost:5432/cun_attend\n# Comma-separated Telegram user IDs bootstrapped as SUPER_ADMIN on startup\nSUPER_ADMIN_TELEGRAM_IDS=8744657740\nLOG_LEVEL=info\n# Defaults (configurable per session later)\nDEFAULT_CODE_ROTATION_MINUTES=5\nDEFAULT_RADIUS_METERS=100\nATTENDANCE_ALERT_THRESHOLD=75\nTIMEZONE=Africa/Lagos\n",
 ".gitignore": "node_modules\ndist\n.env\n*.log\n",
 "README.md": "# CUN Attend\n*Verified Presence. Smarter Attendance. Better Academics.*\n\nPremium academic attendance platform for Claretian University of Nigeria. Telegram bot on Node.js + TypeScript + Telegraf + PostgreSQL.\nFlow: **VERIFY → RECORD → ANALYZE**.\n\n## Features\n- Roles: SUPER_ADMIN, SCHOOL_ADMIN, DEPARTMENT_ADMIN, FACILITATOR, STUDENT, ATTENDANCE_OFFICER (checked server-side on every action)\n- Student self-registration; facilitators/staff authorized only by admins\n- Departments, courses, classrooms (with coordinates) are database records\n- Sessions: course, classroom, verification (code / location / approval / combined), radius, late threshold, duration\n- Secure 4-digit rotating codes (default 5 min), old codes revoked instantly\n- Haversine location check, one-time location only, forwarded locations rejected\n- Facilitator approval with Approve/Reject buttons (session owner only)\n- PRESENT / LATE / ABSENT / EXCUSED / PENDING / REJECTED; `UNIQUE(session_id, student_id)`\n- Auto-expiry, end session → automatic ABSENT, attendance list + CSV\n- Live attendance (paginated), student dashboard, per-course breakdown, history (paginated)\n- Notifications (class opened, session closing, expiry, low attendance, modifications), de-duplicated\n- CSV reports: session, course, student, date range (formatter registry ready for PDF/Excel)\n- Audited attendance modification (previous, new, who, when, reason) and full audit log\n- Suspicious-activity logging, wrong-code throttling, rate limiting, structured logs (pino)\n\n## Run locally\n```\nnpm install\ncp .env.example .env     # TELEGRAM_BOT_TOKEN, DATABASE_URL, SUPER_ADMIN_TELEGRAM_IDS\nnpm run dev              # migrates DB, bootstraps super admin, starts bot + scheduler\nnpm test                 # unit tests; set TEST_DATABASE_URL to also run end-to-end DB tests\n```\n\n## Deploy on Render (Web Service + Postgres)\n- Build: `npm install --include=dev && npm run build`\n- Start: `npm start`\n- Health check path: `/health`\n- Env: `TELEGRAM_BOT_TOKEN`, `DATABASE_URL`, `NODE_ENV=production`, `SUPER_ADMIN_TELEGRAM_IDS`, `TIMEZONE`\n- Run a single instance (the bot uses long polling and one scheduler).\n\n## Structure\n`bot/` (handlers, flows, middleware) → `services/` (rules, authorization, audit) → `repositories/` (SQL) → PostgreSQL (`migrations/`).\nHandlers hold no business logic; a future web dashboard can reuse the same services.\n\n## Privacy and limits\nLocation is requested only when a student chooses location verification and is never tracked. Only the calculated distance is stored.\nNo system makes cheating impossible; layered checks (rotating codes, radius, one record per session, audit trail) raise the cost of it.\n",
 "migrations/001_init.sql": "CREATE EXTENSION IF NOT EXISTS pgcrypto;\n\nCREATE TYPE user_role AS ENUM ('SUPER_ADMIN','SCHOOL_ADMIN','DEPARTMENT_ADMIN','FACILITATOR','STUDENT','ATTENDANCE_OFFICER');\nCREATE TYPE entity_status AS ENUM ('ACTIVE','INACTIVE','SUSPENDED');\nCREATE TYPE session_status AS ENUM ('ACTIVE','EXPIRED','ENDED','CANCELLED');\nCREATE TYPE attendance_status AS ENUM ('PRESENT','LATE','ABSENT','EXCUSED','PENDING','REJECTED');\nCREATE TYPE verification_method AS ENUM ('CLASS_CODE','LOCATION','FACILITATOR_APPROVAL','MANUAL');\nCREATE TYPE request_status AS ENUM ('PENDING','APPROVED','REJECTED','EXPIRED');\n\nCREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger AS $$\nBEGIN NEW.updated_at = now(); RETURN NEW; END; $$ LANGUAGE plpgsql;\n\nCREATE TABLE departments (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name text NOT NULL UNIQUE,\n  code text NOT NULL UNIQUE,\n  status entity_status NOT NULL DEFAULT 'ACTIVE',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- One Telegram account = one identity (UNIQUE telegram_id)\nCREATE TABLE users (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  telegram_id bigint NOT NULL UNIQUE,\n  role user_role NOT NULL,\n  full_name text NOT NULL,\n  status entity_status NOT NULL DEFAULT 'ACTIVE',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE students (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,\n  matric_number text NOT NULL UNIQUE,\n  department_id uuid NOT NULL REFERENCES departments(id),\n  level int NOT NULL CHECK (level BETWEEN 100 AND 700),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX idx_students_dept_level ON students(department_id, level);\n\nCREATE TABLE facilitators (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,\n  staff_id text NOT NULL UNIQUE,\n  department_id uuid NOT NULL REFERENCES departments(id),\n  status entity_status NOT NULL DEFAULT 'ACTIVE',\n  authorized_by uuid REFERENCES users(id),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE admins (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,\n  department_id uuid REFERENCES departments(id),\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE courses (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  code text NOT NULL,\n  title text NOT NULL,\n  department_id uuid NOT NULL REFERENCES departments(id),\n  level int NOT NULL CHECK (level BETWEEN 100 AND 700),\n  semester text NOT NULL CHECK (semester IN ('FIRST','SECOND')),\n  academic_session text NOT NULL,\n  status entity_status NOT NULL DEFAULT 'ACTIVE',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (code, academic_session)\n);\nCREATE INDEX idx_courses_dept_level ON courses(department_id, level);\n\nCREATE TABLE course_facilitators (\n  course_id uuid NOT NULL REFERENCES courses(id) ON DELETE CASCADE,\n  facilitator_id uuid NOT NULL REFERENCES facilitators(id) ON DELETE CASCADE,\n  PRIMARY KEY (course_id, facilitator_id)\n);\n\n-- Optional explicit enrollment (carry-overs, cross-department students)\nCREATE TABLE enrollments (\n  course_id uuid NOT NULL REFERENCES courses(id) ON DELETE CASCADE,\n  student_id uuid NOT NULL REFERENCES students(id) ON DELETE CASCADE,\n  PRIMARY KEY (course_id, student_id)\n);\n\nCREATE TABLE classrooms (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name text NOT NULL UNIQUE,\n  building text NOT NULL,\n  floor int NOT NULL DEFAULT 0,\n  latitude double precision NOT NULL CHECK (latitude BETWEEN -90 AND 90),\n  longitude double precision NOT NULL CHECK (longitude BETWEEN -180 AND 180),\n  default_radius_m int NOT NULL DEFAULT 100 CHECK (default_radius_m BETWEEN 10 AND 1000),\n  status entity_status NOT NULL DEFAULT 'ACTIVE',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE sessions (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  course_id uuid NOT NULL REFERENCES courses(id),\n  facilitator_id uuid NOT NULL REFERENCES facilitators(id),\n  classroom_id uuid NOT NULL REFERENCES classrooms(id),\n  status session_status NOT NULL DEFAULT 'ACTIVE',\n  methods verification_method[] NOT NULL,\n  radius_m int NOT NULL CHECK (radius_m BETWEEN 10 AND 1000),\n  late_after_minutes int NOT NULL DEFAULT 15 CHECK (late_after_minutes >= 0),\n  duration_minutes int NOT NULL CHECK (duration_minutes BETWEEN 5 AND 600),\n  code_rotation_minutes int NOT NULL DEFAULT 5 CHECK (code_rotation_minutes >= 1),\n  latitude double precision NOT NULL,\n  longitude double precision NOT NULL,\n  started_at timestamptz NOT NULL DEFAULT now(),\n  ends_at timestamptz NOT NULL,\n  ended_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX idx_sessions_status_ends ON sessions(status, ends_at);\nCREATE INDEX idx_sessions_facilitator ON sessions(facilitator_id);\n\nCREATE TABLE attendance_codes (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,\n  code char(4) NOT NULL,\n  valid_from timestamptz NOT NULL DEFAULT now(),\n  valid_until timestamptz NOT NULL,\n  revoked_at timestamptz\n);\nCREATE INDEX idx_codes_session_valid ON attendance_codes(session_id, valid_until);\n\nCREATE TABLE attendance (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  session_id uuid NOT NULL REFERENCES sessions(id),\n  student_id uuid NOT NULL REFERENCES students(id),\n  status attendance_status NOT NULL,\n  method verification_method,\n  checked_in_at timestamptz,\n  distance_m numeric(8,2),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (session_id, student_id)\n);\nCREATE INDEX idx_attendance_student ON attendance(student_id, created_at DESC);\n\nCREATE TABLE attendance_changes (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  attendance_id uuid NOT NULL REFERENCES attendance(id),\n  previous_status attendance_status NOT NULL,\n  new_status attendance_status NOT NULL,\n  changed_by uuid NOT NULL REFERENCES users(id),\n  reason text NOT NULL,\n  changed_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE attendance_requests (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  session_id uuid NOT NULL REFERENCES sessions(id),\n  student_id uuid NOT NULL REFERENCES students(id),\n  status request_status NOT NULL DEFAULT 'PENDING',\n  requested_at timestamptz NOT NULL DEFAULT now(),\n  decided_by uuid REFERENCES users(id),\n  decided_at timestamptz\n);\nCREATE UNIQUE INDEX uq_one_pending_request ON attendance_requests(session_id, student_id) WHERE status = 'PENDING';\n\nCREATE TABLE notifications (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  type text NOT NULL,\n  title text NOT NULL,\n  body text NOT NULL,\n  dedupe_key text UNIQUE,\n  read_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX idx_notifications_user ON notifications(user_id, created_at DESC);\n\nCREATE TABLE audit_logs (\n  id bigserial PRIMARY KEY,\n  actor_user_id uuid REFERENCES users(id),\n  action text NOT NULL,\n  entity_type text NOT NULL,\n  entity_id text,\n  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX idx_audit_entity ON audit_logs(entity_type, entity_id);\nCREATE INDEX idx_audit_actor ON audit_logs(actor_user_id, created_at DESC);\n\nDO $$\nDECLARE t text;\nBEGIN\n  FOREACH t IN ARRAY ARRAY['departments','users','students','facilitators','courses','classrooms','attendance']\n  LOOP\n    EXECUTE format('CREATE TRIGGER trg_%s_updated BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION set_updated_at()', t, t);\n  END LOOP;\nEND $$;\n",
 "migrations/002_sessions_extra.sql": "ALTER TYPE verification_method ADD VALUE IF NOT EXISTS 'CODE_AND_LOCATION';\n\nALTER TABLE sessions\n  ADD COLUMN require_combined boolean NOT NULL DEFAULT false,\n  ADD COLUMN card_chat_id bigint,\n  ADD COLUMN card_message_id bigint;\n\n-- Prevent two live sessions for the same course or facilitator\nCREATE UNIQUE INDEX uq_active_session_course ON sessions(course_id) WHERE status = 'ACTIVE';\nCREATE UNIQUE INDEX uq_active_session_facilitator ON sessions(facilitator_id) WHERE status = 'ACTIVE';\n",
 "package.json": "{\n  \"name\": \"cun-attend\",\n  \"version\": \"0.1.0\",\n  \"description\": \"CUN Attend - Verified Presence. Smarter Attendance. Better Academics.\",\n  \"private\": true,\n  \"main\": \"dist/server.js\",\n  \"scripts\": {\n    \"dev\": \"tsx watch src/server.ts\",\n    \"build\": \"tsc -p tsconfig.json\",\n    \"start\": \"node dist/server.js\",\n    \"migrate\": \"tsx src/database/migrate.ts\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"test\": \"vitest run\"\n  },\n  \"dependencies\": {\n    \"dotenv\": \"^16.4.5\",\n    \"express\": \"^4.19.2\",\n    \"pg\": \"^8.12.0\",\n    \"pino\": \"^9.3.2\",\n    \"telegraf\": \"^4.16.3\",\n    \"zod\": \"^3.23.8\"\n  },\n  \"devDependencies\": {\n    \"@types/express\": \"^4.17.21\",\n    \"@types/node\": \"^20.14.12\",\n    \"@types/pg\": \"^8.11.6\",\n    \"tsx\": \"^4.16.2\",\n    \"typescript\": \"^5.5.4\",\n    \"vitest\": \"^2.0.5\"\n  }\n}\n",
 "src/app.ts": "import express from 'express';\nimport { pool } from './database/pool';\n\nexport function createApp() {\n  const app = express();\n  app.get('/health', async (_req, res) => {\n    try { await pool.query('SELECT 1'); res.json({ status: 'ok' }); }\n    catch { res.status(503).json({ status: 'degraded' }); }\n  });\n  return app; // future dashboard REST routes mount here (src/routes)\n}\n",
 "src/bot/context.ts": "import { Context } from 'telegraf';\nimport { AppUser } from '../types';\n\nexport interface Choice { label: string; value: string }\nexport interface FlowState { name: string; step: number; data: Record<string, any>; choices?: Choice[] }\nexport interface SessionData { flow?: FlowState }\nexport interface BotContext extends Context { session: SessionData }\n\nexport const getUser = (ctx: BotContext): AppUser | undefined => (ctx.state as any).user;\n",
 "src/bot/flows/definitions.ts": "import { z } from 'zod';\nimport { pool } from '../../database/pool';\nimport { users } from '../../repositories';\nimport { ADMIN_ROLES, Roles } from '../../types';\nimport { classroomService, courseService, departmentService, facilitatorService, studentService } from '../../services/registry';\nimport { esc } from '../../utils/format';\nimport { getUser } from '../context';\nimport { showHome } from '../handlers/home';\nimport { registerFlow } from './engine';\n\nconst isAdmin = (u: any) => !!u && u.status === 'ACTIVE' && ADMIN_ROLES.includes(u.role);\nconst deptChoices = async () => (await departmentService.list()).map((d) => ({ label: d.name, value: d.id }));\nconst levels = async () => [100, 200, 300, 400, 500].map((l) => ({ label: `${l} Level`, value: String(l) }));\nconst confirm = async () => [{ label: '✅ Confirm', value: 'yes' }];\nconst name = (max = 100) => z.string().trim().min(2, 'Too short').max(max, 'Too long');\n\nregisterFlow({\n  name: 'registerStudent',\n  allow: (u) => !u,\n  steps: [\n    { key: 'fullName', kind: 'text', prompt: 'Enter your <b>full name</b> as on university records.', schema: z.string().trim().min(3).max(100).regex(/^[\\p{L}][\\p{L} .'\\-]+$/u, 'Use letters only') },\n    { key: 'matric', kind: 'text', prompt: 'Enter your <b>matric number</b>.', schema: z.string().trim().toUpperCase().min(4).max(30).regex(/^[A-Z0-9\\/\\-]+$/, 'Use letters, digits, / or -') },\n    { key: 'departmentId', kind: 'choice', prompt: 'Select your <b>department</b>.', choices: deptChoices, emptyMessage: 'No departments are configured yet. Please contact administration.' },\n    { key: 'level', kind: 'choice', prompt: 'Select your <b>level</b>.', choices: levels },\n    { key: 'confirm', kind: 'choice', choices: confirm,\n      prompt: (_c, d) => `<b>Confirm your details</b>\\n\\n👤 ${esc(d.fullName)}\\n🆔 ${esc(d.matric)}\\n🏛 ${esc(d.departmentIdLabel)}\\n🎓 ${esc(d.levelLabel)}` },\n  ],\n  complete: async (ctx, d) => {\n    await studentService.register({ telegramId: String(ctx.from!.id), fullName: d.fullName, matric: d.matric, departmentId: d.departmentId, level: Number(d.level) });\n    await ctx.reply('✅ Registration complete. Welcome to CUN Attend!');\n    (ctx.state as any).user = await users.findByTelegramId(pool, String(ctx.from!.id));\n    await showHome(ctx);\n  },\n});\n\nregisterFlow({\n  name: 'addDepartment', allow: isAdmin,\n  steps: [\n    { key: 'name', kind: 'text', prompt: 'Department <b>name</b>?', schema: name() },\n    { key: 'code', kind: 'text', prompt: 'Department <b>code</b> (e.g. CSC)?', schema: z.string().trim().toUpperCase().min(2).max(10).regex(/^[A-Z0-9]+$/, 'Letters/digits only') },\n  ],\n  complete: async (ctx, d) => { await departmentService.create(getUser(ctx), d.name, d.code); await ctx.reply(`✅ Department <b>${esc(d.name)}</b> created.`, { parse_mode: 'HTML' }); },\n});\n\nregisterFlow({\n  name: 'addFacilitator', allow: isAdmin,\n  steps: [\n    { key: 'telegramId', kind: 'text', prompt: \"Facilitator's <b>Telegram ID</b> (numeric). They can get it from @userinfobot.\", schema: z.string().trim().regex(/^\\d{5,15}$/, 'Must be 5–15 digits') },\n    { key: 'fullName', kind: 'text', prompt: \"Facilitator's <b>full name</b>?\", schema: name() },\n    { key: 'staffId', kind: 'text', prompt: '<b>Staff ID</b>?', schema: z.string().trim().toUpperCase().min(2).max(30).regex(/^[A-Z0-9\\/\\-]+$/, 'Letters, digits, / or -') },\n    { key: 'departmentId', kind: 'choice', prompt: 'Select <b>department</b>.', choices: deptChoices, emptyMessage: 'Create a department first.' },\n  ],\n  complete: async (ctx, d) => {\n    await facilitatorService.authorize(getUser(ctx), { telegramId: d.telegramId, fullName: d.fullName, staffId: d.staffId, departmentId: d.departmentId });\n    await ctx.reply(`✅ <b>${esc(d.fullName)}</b> authorized. They can now send /start.`, { parse_mode: 'HTML' });\n  },\n});\n\nregisterFlow({\n  name: 'addCourse', allow: isAdmin,\n  steps: [\n    { key: 'code', kind: 'text', prompt: 'Course <b>code</b> (e.g. CSC 405)?', schema: z.string().trim().toUpperCase().min(3).max(15).regex(/^[A-Z0-9 ]+$/, 'Letters/digits only') },\n    { key: 'title', kind: 'text', prompt: 'Course <b>title</b>?', schema: name(120) },\n    { key: 'departmentId', kind: 'choice', prompt: 'Select <b>department</b>.', choices: deptChoices, emptyMessage: 'Create a department first.' },\n    { key: 'level', kind: 'choice', prompt: 'Select <b>level</b>.', choices: levels },\n    { key: 'semester', kind: 'choice', prompt: 'Select <b>semester</b>.', choices: async () => [{ label: 'First', value: 'FIRST' }, { label: 'Second', value: 'SECOND' }] },\n    { key: 'session', kind: 'text', prompt: 'Academic session (e.g. 2025/2026)?', schema: z.string().trim().regex(/^\\d{4}\\/\\d{4}$/, 'Use format 2025/2026') },\n  ],\n  complete: async (ctx, d) => {\n    await courseService.create(getUser(ctx), { code: d.code, title: d.title, departmentId: d.departmentId, level: Number(d.level), semester: d.semester, session: d.session });\n    await ctx.reply(`✅ Course <b>${esc(d.code)}</b> created.`, { parse_mode: 'HTML' });\n  },\n});\n\nregisterFlow({\n  name: 'assignCourse', allow: isAdmin,\n  steps: [\n    { key: 'courseId', kind: 'choice', prompt: 'Select <b>course</b>.', emptyMessage: 'No courses yet.', choices: async () => (await courseService.list()).map((c) => ({ label: `${c.code} – ${c.title}`, value: c.id })) },\n    { key: 'facilitatorId', kind: 'choice', prompt: 'Select <b>facilitator</b>.', emptyMessage: 'No facilitators yet.', choices: async () => (await facilitatorService.list()).map((f) => ({ label: f.full_name, value: f.id })) },\n  ],\n  complete: async (ctx, d) => { await courseService.assignFacilitator(getUser(ctx), d.courseId, d.facilitatorId); await ctx.reply('✅ Facilitator assigned to course.'); },\n});\n\nregisterFlow({\n  name: 'addClassroom', allow: isAdmin,\n  steps: [\n    { key: 'name', kind: 'text', prompt: 'Classroom <b>name</b> (e.g. ICT Laboratory 1)?', schema: name() },\n    { key: 'building', kind: 'text', prompt: '<b>Building</b>?', schema: name() },\n    { key: 'floor', kind: 'text', prompt: '<b>Floor</b> number (0 = ground)?', schema: z.coerce.number().int().min(-2).max(50) },\n    { key: 'location', kind: 'location', prompt: '📍 Stand in the classroom and share a <b>location</b> using the 📎 attachment menu. Only this one-time coordinate is stored.' },\n    { key: 'radius', kind: 'choice', prompt: 'Default verification <b>radius</b>?', choices: async () => [50, 100, 150].map((r) => ({ label: `${r} m`, value: String(r) })) },\n  ],\n  complete: async (ctx, d) => {\n    await classroomService.create(getUser(ctx), { name: d.name, building: d.building, floor: d.floor, latitude: d.location.lat, longitude: d.location.lng, radius: Number(d.radius) });\n    await ctx.reply(`✅ Classroom <b>${esc(d.name)}</b> created.`, { parse_mode: 'HTML' });\n  },\n});\n\nexport const _roles = Roles; // keep import used for future role-specific flows\n",
 "src/bot/flows/engine.ts": "import { Markup } from 'telegraf';\nimport { z } from 'zod';\nimport { AppUser } from '../../types';\nimport { ForbiddenError } from '../../utils/errors';\nimport { BotContext, Choice, getUser } from '../context';\n\nexport interface Step {\n  key: string;\n  kind: 'text' | 'choice' | 'location';\n  prompt: string | ((ctx: BotContext, data: Record<string, any>) => string);\n  schema?: z.ZodTypeAny;\n  choices?: (ctx: BotContext, data: Record<string, any>) => Promise<Choice[]>;\n  emptyMessage?: string;\n  skip?: (data: Record<string, any>) => boolean;\n  locationButton?: boolean;\n}\nexport interface FlowDef {\n  name: string;\n  allow: (user: AppUser | undefined) => boolean;\n  steps: Step[];\n  complete: (ctx: BotContext, data: Record<string, any>) => Promise<void>;\n}\n\nconst flows = new Map<string, FlowDef>();\nexport const registerFlow = (f: FlowDef) => flows.set(f.name, f);\n\nconst CANCEL_TEXT = '✖ Cancel';\nconst cancelRow = [Markup.button.callback('✖ Cancel', 'flow:cancel')];\nconst send = (ctx: BotContext, html: string, rows: any[][] = [cancelRow]) =>\n  ctx.reply(html, { parse_mode: 'HTML', ...Markup.inlineKeyboard(rows) });\n\nconst seek = (def: FlowDef, from: number, data: Record<string, any>) => {\n  let i = from;\n  while (i < def.steps.length && def.steps[i].skip?.(data)) i++;\n  return i;\n};\n\nexport async function startFlow(ctx: BotContext, name: string) {\n  const def = flows.get(name);\n  if (!def || !def.allow(getUser(ctx))) throw new ForbiddenError();\n  ctx.session.flow = { name, step: seek(def, 0, {}), data: {} };\n  await prompt(ctx);\n}\n\nasync function prompt(ctx: BotContext) {\n  const flow = ctx.session.flow!;\n  const step = flows.get(flow.name)!.steps[flow.step];\n  const text = typeof step.prompt === 'function' ? step.prompt(ctx, flow.data) : step.prompt;\n  if (step.kind === 'choice') {\n    const choices = await step.choices!(ctx, flow.data);\n    if (!choices.length) {\n      ctx.session.flow = undefined;\n      await ctx.reply(step.emptyMessage ?? 'Nothing available yet.');\n      return;\n    }\n    flow.choices = choices; // server-side record of what was offered\n    const rows = choices.map((c, i) => [Markup.button.callback(c.label, `flow:pick:${i}`)]);\n    await send(ctx, text, [...rows, cancelRow]);\n  } else if (step.kind === 'location' && step.locationButton) {\n    await ctx.reply(text, { parse_mode: 'HTML', ...Markup.keyboard([[Markup.button.locationRequest('📍 Share my location')], [CANCEL_TEXT]]).oneTime().resize() });\n  } else {\n    await send(ctx, text);\n  }\n}\n\nasync function advance(ctx: BotContext, key: string, value: any, label?: string) {\n  const flow = ctx.session.flow!;\n  const def = flows.get(flow.name)!;\n  flow.data[key] = value;\n  if (label !== undefined) flow.data[`${key}Label`] = label;\n  flow.step = seek(def, flow.step + 1, flow.data);\n  if (flow.step >= def.steps.length) {\n    const data = flow.data;\n    ctx.session.flow = undefined;\n    if (!def.allow(getUser(ctx))) throw new ForbiddenError(); // re-check at completion\n    await def.complete(ctx, data);\n  } else {\n    await prompt(ctx);\n  }\n}\n\nexport async function onText(ctx: BotContext, text: string): Promise<boolean> {\n  const flow = ctx.session.flow;\n  if (!flow) return false;\n  if (text === CANCEL_TEXT) { await cancelFlow(ctx); return true; }\n  const step = flows.get(flow.name)!.steps[flow.step];\n  if (step.kind !== 'text') { await ctx.reply('Please use the buttons above, or /cancel.'); return true; }\n  const res = (step.schema ?? z.string().trim().min(1)).safeParse(text);\n  if (!res.success) { await ctx.reply(`❌ ${res.error.issues[0].message}. Try again.`); return true; }\n  await advance(ctx, step.key, res.data);\n  return true;\n}\n\nexport async function onPick(ctx: BotContext, indexStr: string) {\n  const flow = ctx.session.flow;\n  const idx = Number(indexStr);\n  const choice = flow?.choices?.[idx];\n  if (!flow || !Number.isInteger(idx) || !choice) { await ctx.reply('That option has expired. Send /start to begin again.'); return; }\n  const step = flows.get(flow.name)!.steps[flow.step];\n  if (step.kind !== 'choice') return;\n  flow.choices = undefined;\n  await advance(ctx, step.key, choice.value, choice.label);\n}\n\nexport async function onLocation(ctx: BotContext, lat: number, lng: number, forwarded: boolean) {\n  const flow = ctx.session.flow;\n  if (!flow) return;\n  const step = flows.get(flow.name)!.steps[flow.step];\n  if (step.kind !== 'location') return;\n  if (step.locationButton) await ctx.reply('📡 Verifying…', Markup.removeKeyboard());\n  await advance(ctx, step.key, { lat, lng, forwarded });\n}\n\nexport async function cancelFlow(ctx: BotContext) {\n  ctx.session.flow = undefined;\n  await ctx.reply('Cancelled. Send /start to return to the menu.', Markup.removeKeyboard());\n}\n",
 "src/bot/flows/operations.ts": "import { z } from 'zod';\nimport { pool } from '../../database/pool';\nimport { attendanceService } from '../../services/attendance';\nimport { adminService } from '../../services/admin';\nimport { broadcast } from '../../services/notifier';\nimport { reportService, ReportKind } from '../../services/reports';\nimport { courseService } from '../../services/registry';\nimport { eligibleSql, sessionService } from '../../services/sessions';\nimport { ADMIN_ROLES, AppUser, Role, Roles } from '../../types';\nimport { esc, LINE } from '../../utils/format';\nimport { METHOD_LABEL } from '../../utils/status';\nimport { fmtDate, fmtTime } from '../../utils/time';\nimport { BotContext, getUser } from '../context';\nimport { sendApprovalRequest, sendCard } from '../handlers/facilitator';\nimport { registerFlow } from './engine';\nimport { env } from '../../config/env';\n\nconst is = (...roles: Role[]) => (u: AppUser | undefined) => !!u && u.status === 'ACTIVE' && roles.includes(u.role);\nconst STAFF: Role[] = [Roles.FACILITATOR, Roles.ATTENDANCE_OFFICER, ...ADMIN_ROLES];\nconst opt = (label: string, value: string) => ({ label, value });\n\nconst PRESETS: Record<string, { label: string; methods: string[]; combined: boolean }> = {\n  CODE: { label: '🔑 Class Code', methods: ['CLASS_CODE'], combined: false },\n  LOCATION: { label: '📍 Location', methods: ['LOCATION'], combined: false },\n  APPROVAL: { label: '✋ Facilitator Approval', methods: ['FACILITATOR_APPROVAL'], combined: false },\n  EITHER: { label: '🔑/📍 Code or Location', methods: ['CLASS_CODE', 'LOCATION'], combined: false },\n  BOTH: { label: '🔑+📍 Code AND Location (both required)', methods: ['CLASS_CODE', 'LOCATION'], combined: true },\n  ALL: { label: '🔑📍✋ All methods (any one)', methods: ['CLASS_CODE', 'LOCATION', 'FACILITATOR_APPROVAL'], combined: false },\n};\n\n// ---------- Start a class session (facilitator) ----------\nregisterFlow({\n  name: 'newSession', allow: is(Roles.FACILITATOR),\n  steps: [\n    { key: 'courseId', kind: 'choice', prompt: '1/6 · Select the <b>course</b>.', emptyMessage: 'You have no assigned courses. Ask an administrator to assign you.',\n      choices: async (ctx) => (await sessionService.coursesForFacilitator(getUser(ctx)!)).map((c) => opt(`${c.code} – ${c.title}`, c.id)) },\n    { key: 'classroomId', kind: 'choice', prompt: '2/6 · Select the <b>classroom</b>.', emptyMessage: 'No classrooms configured yet.',\n      choices: async () => (await pool.query<{ id: string; name: string }>(`SELECT id, name FROM classrooms WHERE status='ACTIVE' ORDER BY name`)).rows.map((r) => opt(`📍 ${r.name}`, r.id)) },\n    { key: 'preset', kind: 'choice', prompt: '3/6 · Choose <b>verification</b>.', choices: async () => Object.entries(PRESETS).map(([k, v]) => opt(v.label, k)) },\n    { key: 'radius', kind: 'choice', prompt: '4/6 · Location <b>radius</b>.', skip: (d) => !PRESETS[d.preset]?.methods.includes('LOCATION'),\n      choices: async () => [50, 100, 150].map((r) => opt(`${r} m`, String(r))) },\n    { key: 'late', kind: 'choice', prompt: '5/6 · Mark students <b>Late</b> after…', choices: async () => [5, 10, 15, 30].map((m) => opt(`${m} minutes`, String(m))) },\n    { key: 'duration', kind: 'choice', prompt: '6/6 · Session <b>duration</b>.', choices: async () => [30, 60, 90, 120, 180].map((m) => opt(`${m} minutes`, String(m))) },\n    { key: 'confirm', kind: 'choice', choices: async () => [opt('✅ Start session', 'yes')],\n      prompt: (_c, d) => `<b>Confirm session</b>\\n\\n📚 ${esc(d.courseIdLabel)}\\n${esc(d.classroomIdLabel)}\\n🔎 ${esc(PRESETS[d.preset].label)}\\n${d.radius ? `📏 ${d.radius} m radius\\n` : ''}⏱ Late after ${d.late} min · Duration ${d.duration} min\\n🔄 Code rotates every ${env.DEFAULT_CODE_ROTATION_MINUTES} min` },\n  ],\n  complete: async (ctx, d) => {\n    const p = PRESETS[d.preset];\n    const { session } = await sessionService.create(getUser(ctx), {\n      courseId: d.courseId, classroomId: d.classroomId, methods: p.methods, requireCombined: p.combined,\n      radius: Number(d.radius ?? env.DEFAULT_RADIUS_METERS), lateMinutes: Number(d.late), durationMinutes: Number(d.duration),\n    });\n    await sendCard(ctx, session.id);\n    // Tell eligible students (paced, not awaited).\n    const students = (await pool.query<{ telegram_id: string }>(`SELECT telegram_id FROM (${eligibleSql(1)}) e`, [session.course_id])).rows;\n    void broadcast(students.map((s) => ({ telegramId: s.telegram_id, html: `🟢 <b>${esc(session.course_code)}</b> is now open in ${esc(session.room_name)}.\\nSend /checkin to record your attendance.` })));\n  },\n});\n\n// ---------- Student check-in ----------\nconst methodChoices = async (sessionId: string) => {\n  const s = await sessionService.get(sessionId);\n  if (!s || s.status !== 'ACTIVE') return [];\n  const out = [];\n  if (s.require_combined) out.push(opt('🔑📍 Code + Location', 'COMBINED'));\n  else for (const m of s.methods) out.push(opt(m === 'CLASS_CODE' ? '🔑 Class Code' : m === 'LOCATION' ? '📍 Location' : '✋ Facilitator Approval', m));\n  if (s.require_combined && s.methods.includes('FACILITATOR_APPROVAL')) out.push(opt('✋ Facilitator Approval', 'FACILITATOR_APPROVAL'));\n  return out;\n};\n\nregisterFlow({\n  name: 'checkIn', allow: is(Roles.STUDENT),\n  steps: [\n    { key: 'sessionId', kind: 'choice', prompt: 'Select your <b>class</b>.', emptyMessage: 'No active classes available for you right now.',\n      choices: async (ctx) => (await attendanceService.activeFor(getUser(ctx)!)).map((s) => opt(`${s.code} – ${s.room}`, s.id)) },\n    { key: 'method', kind: 'choice', prompt: 'Choose how to <b>verify</b>.', emptyMessage: 'This class is no longer open.', choices: async (_c, d) => methodChoices(d.sessionId) },\n    { key: 'code', kind: 'text', skip: (d) => !['CLASS_CODE', 'COMBINED'].includes(d.method), prompt: 'Enter the <b>4-digit class code</b> shown by your facilitator.', schema: z.string().trim().regex(/^\\d{4}$/, 'Code must be 4 digits') },\n    { key: 'location', kind: 'location', locationButton: true, skip: (d) => !['LOCATION', 'COMBINED'].includes(d.method),\n      prompt: '📍 Tap the button to share your <b>current location</b>. It is used once, for this check-in only.' },\n  ],\n  complete: async (ctx, d) => {\n    const user = getUser(ctx)!;\n    const r = await attendanceService.checkIn(user, { sessionId: d.sessionId, method: d.method, code: d.code, location: d.location });\n    if (r.kind === 'PENDING_APPROVAL') {\n      await sendApprovalRequest(r.facilitatorTelegramId, { requestId: r.requestId, studentName: r.studentName, matric: r.matric, courseCode: r.courseCode, at: r.at });\n      return void ctx.reply('✋ Request sent to your facilitator. You will be notified once they decide.');\n    }\n    await ctx.reply(`${LINE}\\n✅ <b>Attendance Confirmed</b>\\n${LINE}\\n\\n📚 ${esc(r.courseCode)} – ${esc(r.courseTitle)}\\n🕐 ${fmtTime(r.at)}\\n🔎 ${METHOD_LABEL[r.method] ?? r.method}${r.distanceM !== undefined ? `\\n📏 ${Math.round(r.distanceM)} m from classroom` : ''}\\n📌 ${r.status}\\n${LINE}`, { parse_mode: 'HTML' });\n  },\n});\n\n// ---------- Attendance modification (audited) ----------\nregisterFlow({\n  name: 'modifyAttendance', allow: is(...STAFF),\n  steps: [\n    { key: 'sessionId', kind: 'choice', prompt: 'Select the <b>session</b>.', emptyMessage: 'No sessions found.',\n      choices: async (ctx) => (await sessionService.recentForActor(getUser(ctx)!)).map((s) => opt(`${s.course_code} · ${fmtDate(s.started_at)} ${fmtTime(s.started_at)}`, s.id)) },\n    { key: 'matric', kind: 'text', prompt: \"Enter the student's <b>matric number</b>.\", schema: z.string().trim().toUpperCase().min(4).max(30) },\n    { key: 'status', kind: 'choice', prompt: 'New <b>status</b>?', choices: async () => ['PRESENT', 'LATE', 'EXCUSED', 'ABSENT'].map((s) => opt(s, s)) },\n    { key: 'reason', kind: 'text', prompt: 'Enter the <b>reason</b> for this change (recorded in the audit log).', schema: z.string().trim().min(3, 'Please give a reason').max(300) },\n  ],\n  complete: async (ctx, d) => {\n    const r = await attendanceService.modify(getUser(ctx), { sessionId: d.sessionId, matric: d.matric, newStatus: d.status, reason: d.reason });\n    await ctx.reply(`✅ ${esc(r.studentName)} (${esc(r.courseCode)}): ${r.previous} → ${r.newStatus}. Change logged.`, { parse_mode: 'HTML' });\n  },\n});\n\n// ---------- Reports ----------\nasync function sendReport(ctx: BotContext, kind: ReportKind, args: Parameters<typeof reportService.generate>[2]) {\n  const rep = await reportService.generate(getUser(ctx), kind, args);\n  if (!rep.rowCount) return void ctx.reply('No attendance records matched.');\n  await ctx.reply(`📄 ${rep.rowCount} records`);\n  await ctx.replyWithDocument({ source: rep.content, filename: rep.filename });\n}\nconst courseChoices = async (ctx: BotContext) => {\n  const u = getUser(ctx)!;\n  const list = u.role === Roles.FACILITATOR ? await sessionService.coursesForFacilitator(u) : await courseService.list();\n  return list.map((c) => opt(`${c.code} – ${c.title}`, c.id));\n};\nconst dateSchema = z.string().trim().regex(/^\\d{4}-\\d{2}-\\d{2}$/, 'Use YYYY-MM-DD');\n\nregisterFlow({ name: 'reportSession', allow: is(...STAFF), steps: [\n  { key: 'sessionId', kind: 'choice', prompt: 'Which <b>session</b>?', emptyMessage: 'No sessions yet.',\n    choices: async (ctx) => (await sessionService.recentForActor(getUser(ctx)!, 10)).map((s) => opt(`${s.course_code} · ${fmtDate(s.started_at)} ${fmtTime(s.started_at)}`, s.id)) }],\n  complete: (ctx, d) => sendReport(ctx, 'SESSION', { sessionId: d.sessionId }) });\nregisterFlow({ name: 'reportCourse', allow: is(...STAFF), steps: [\n  { key: 'courseId', kind: 'choice', prompt: 'Which <b>course</b>?', emptyMessage: 'No courses available.', choices: courseChoices }],\n  complete: (ctx, d) => sendReport(ctx, 'COURSE', { courseId: d.courseId }) });\nregisterFlow({ name: 'reportStudent', allow: is(...STAFF), steps: [\n  { key: 'matric', kind: 'text', prompt: \"Enter the student's <b>matric number</b>.\", schema: z.string().trim().toUpperCase().min(4).max(30) }],\n  complete: (ctx, d) => sendReport(ctx, 'STUDENT', { matric: d.matric }) });\nregisterFlow({ name: 'reportRange', allow: is(...STAFF), steps: [\n  { key: 'from', kind: 'text', prompt: '<b>From</b> date (YYYY-MM-DD)?', schema: dateSchema },\n  { key: 'to', kind: 'text', prompt: '<b>To</b> date (YYYY-MM-DD)?', schema: dateSchema }],\n  complete: (ctx, d) => sendReport(ctx, 'RANGE', { from: d.from, to: d.to }) });\n\n// ---------- Create staff accounts (super admin) ----------\nregisterFlow({\n  name: 'addAdmin', allow: is(Roles.SUPER_ADMIN),\n  steps: [\n    { key: 'telegramId', kind: 'text', prompt: 'Their <b>Telegram ID</b> (numeric)?', schema: z.string().trim().regex(/^\\d{5,15}$/, 'Must be 5–15 digits') },\n    { key: 'fullName', kind: 'text', prompt: '<b>Full name</b>?', schema: z.string().trim().min(2).max(100) },\n    { key: 'role', kind: 'choice', prompt: 'Select <b>role</b>.', choices: async () => [opt('School Admin', Roles.SCHOOL_ADMIN), opt('Department Admin', Roles.DEPARTMENT_ADMIN), opt('Attendance Officer', Roles.ATTENDANCE_OFFICER)] },\n    { key: 'departmentId', kind: 'choice', prompt: 'Select <b>department</b>.', skip: (d) => d.role !== Roles.DEPARTMENT_ADMIN, emptyMessage: 'Create a department first.',\n      choices: async () => (await pool.query<{ id: string; name: string }>(`SELECT id, name FROM departments WHERE status='ACTIVE' ORDER BY name`)).rows.map((r) => opt(r.name, r.id)) },\n  ],\n  complete: async (ctx, d) => {\n    await adminService.createAdmin(getUser(ctx), { telegramId: d.telegramId, fullName: d.fullName, role: d.role, departmentId: d.departmentId });\n    await ctx.reply(`✅ ${esc(d.fullName)} added as ${d.role}. They can now send /start.`, { parse_mode: 'HTML' });\n  },\n});\n",
 "src/bot/handlers/cards.ts": "import { Markup } from 'telegraf';\nimport { pool } from '../../database/pool';\nimport { counts, currentCode, getSession, SessionDetail } from '../../services/sessions';\nimport { sessionService } from '../../services/sessions';\nimport { getTelegram } from '../../services/notifier';\nimport { LINE, esc } from '../../utils/format';\nimport { fmtTime } from '../../utils/time';\nimport { logger } from '../../utils/logger';\n\nconst STATE: Record<string, string> = { ACTIVE: '🟢 SESSION ACTIVE', EXPIRED: '🟠 SESSION EXPIRED', ENDED: '⚪ SESSION ENDED', CANCELLED: '⚫ CANCELLED' };\n\nexport async function buildCard(sessionId: string) {\n  const s = (await getSession(pool, sessionId))!;\n  const c = await counts(pool, s);\n  const code = s.status === 'ACTIVE' && s.methods.includes('CLASS_CODE') ? await currentCode(pool, s.id) : undefined;\n  const lines = [\n    LINE, '🎓 <b>CUN ATTEND</b>', LINE, '', `<b>${STATE[s.status]}</b>`, '',\n    `<b>${esc(s.course_code)}</b>`, esc(s.course_title), '',\n    `📍 ${esc(s.room_name)}`, `👨‍🏫 ${esc(s.facilitator_name)}`, `🕐 ${fmtTime(s.started_at)} – ${fmtTime(s.ends_at)}`,\n  ];\n  if (code) lines.push(`🔑 Code: <code>${code.code}</code> (until ${fmtTime(code.valid_until)})`);\n  lines.push('', `👥 ${c.present} Present`, `🟡 ${c.late} Late`, `⏳ ${c.pending} Pending`, `🔴 ${c.absent} Absent`, LINE);\n  const open = s.status === 'ACTIVE' || s.status === 'EXPIRED';\n  const rows = open\n    ? [[Markup.button.callback('🔄 Refresh', `ses:r:${s.id}`), Markup.button.callback('👥 Live', `ses:l:${s.id}:0`)],\n       [Markup.button.callback('⏹ End Session', `ses:e:${s.id}`)]]\n    : [[Markup.button.callback('👥 Final list', `ses:l:${s.id}:0`)]];\n  return { text: lines.join('\\n'), rows, session: s as SessionDetail };\n}\n\n/** Edit the stored facilitator card in place (used by the scheduler on rotation/expiry). */\nexport async function refreshStoredCard(sessionId: string) {\n  const tg = getTelegram();\n  if (!tg) return;\n  const s = await sessionService.get(sessionId);\n  if (!s?.card_chat_id || !s.card_message_id) return;\n  try {\n    const { text, rows } = await buildCard(sessionId);\n    await tg.editMessageText(s.card_chat_id, Number(s.card_message_id), undefined, text, { parse_mode: 'HTML', ...Markup.inlineKeyboard(rows) } as any);\n  } catch (err) {\n    if (!String((err as Error).message).includes('not modified')) logger.warn({ err: (err as Error).message }, 'card refresh failed');\n  }\n}\n",
 "src/bot/handlers/facilitator.ts": "import { Markup } from 'telegraf';\nimport { pool } from '../../database/pool';\nimport { attendanceService } from '../../services/attendance';\nimport { sendTelegram } from '../../services/notifier';\nimport { reportService } from '../../services/reports';\nimport { counts, getSession, sessionService, assertSessionAccess } from '../../services/sessions';\nimport { liveList } from '../../services/stats';\nimport { LINE, esc } from '../../utils/format';\nimport { STATUS_ICON } from '../../utils/status';\nimport { fmtTime } from '../../utils/time';\nimport { BotContext, getUser } from '../context';\nimport { buildCard, refreshStoredCard } from './cards';\n\nexport async function edit(ctx: BotContext, html: string, rows: any[][] = []) {\n  const extra = { parse_mode: 'HTML' as const, ...Markup.inlineKeyboard(rows.filter((r) => r.length)) };\n  if (ctx.callbackQuery) {\n    try { await ctx.editMessageText(html, extra); return; }\n    catch (e) { if (String((e as Error).message).includes('not modified')) return; }\n  }\n  await ctx.reply(html, extra);\n}\n\nexport async function sendCard(ctx: BotContext, sessionId: string) {\n  const { text, rows } = await buildCard(sessionId);\n  const msg = await ctx.reply(text, { parse_mode: 'HTML', ...Markup.inlineKeyboard(rows) });\n  await sessionService.saveCard(sessionId, msg.chat.id, msg.message_id);\n}\n\nexport async function showActiveSession(ctx: BotContext) {\n  const s = await sessionService.activeForFacilitator(getUser(ctx)!);\n  if (!s) return void ctx.reply('You have no active session. Use /newsession to start one.');\n  await sendCard(ctx, s.id);\n}\n\nexport async function showEndConfirm(ctx: BotContext, sessionId?: string) {\n  const user = getUser(ctx)!;\n  const id = sessionId ?? (await sessionService.activeForFacilitator(user))?.id;\n  if (!id) return void ctx.reply('You have no active session to end.');\n  const { session, counts: c } = await sessionService.summary(user, id);\n  await edit(ctx, `${LINE}\\n<b>End ${esc(session.course_code)}?</b>\\n${LINE}\\n\\n🟢 ${c.present} Present\\n🟡 ${c.late} Late\\n⏳ ${c.pending} Pending (will become Absent)\\n🔴 ${c.absent} Absent (incl. not yet checked in)\\n\\nStudents without a record are marked <b>Absent</b>.`,\n    [[Markup.button.callback('✅ End session', `ses:ok:${id}`), Markup.button.callback('↩ Keep open', `ses:no:${id}`)]]);\n}\n\nexport async function showLive(ctx: BotContext, sessionId: string, page: number) {\n  const user = getUser(ctx)!;\n  const { session } = await sessionService.summary(user, sessionId);\n  const p = Math.max(0, page);\n  const { rows, total, pages } = await liveList(sessionId, session.course_id, p);\n  if (!total) return void edit(ctx, 'No eligible students found for this course.', [[Markup.button.callback('⬅ Back', `ses:r:${sessionId}`)]]);\n  const body = rows.map((r) => `${STATUS_ICON[r.status] ?? '•'} ${esc(r.full_name)} <i>${esc(r.matric_number)}</i>`).join('\\n');\n  const nav = [];\n  if (p > 0) nav.push(Markup.button.callback('◀ Prev', `ses:l:${sessionId}:${p - 1}`));\n  if (p < pages - 1) nav.push(Markup.button.callback('Next ▶', `ses:l:${sessionId}:${p + 1}`));\n  await edit(ctx, `<b>${esc(session.course_code)} – live</b> (page ${p + 1}/${pages})\\n\\n${body}`, [nav, [Markup.button.callback('⬅ Back to session', `ses:r:${sessionId}`)]]);\n}\n\nexport async function onSessionAction(ctx: BotContext, act: string, id: string, page: number) {\n  const user = getUser(ctx)!;\n  if (act === 'r') {\n    await sessionService.summary(user, id); // authorizes\n    const { text, rows } = await buildCard(id);\n    return void edit(ctx, text, rows);\n  }\n  if (act === 'l') return showLive(ctx, id, page);\n  if (act === 'e') return showEndConfirm(ctx, id);\n  if (act === 'no') { await sessionService.summary(user, id); const { text, rows } = await buildCard(id); return void edit(ctx, text, rows); }\n  if (act === 'ok') {\n    const { session, counts: c } = await sessionService.end(user, id);\n    await edit(ctx, `✅ <b>${esc(session.course_code)} ended.</b>\\n\\n🟢 ${c.present} Present · 🟡 ${c.late} Late · 🔴 ${c.absent} Absent · 🔵 ${c.excused} Excused`, []);\n    const first = await liveList(id, session.course_id, 0);\n    await ctx.reply(`<b>Attendance list</b> (first ${first.rows.length} of ${first.total})\\n\\n` + first.rows.map((r) => `${STATUS_ICON[r.status] ?? '•'} ${esc(r.full_name)}`).join('\\n') + '\\n\\nFull list attached as CSV.', { parse_mode: 'HTML' });\n    const rep = await reportService.generate(user, 'SESSION', { sessionId: id });\n    await ctx.replyWithDocument({ source: rep.content, filename: rep.filename });\n    await refreshStoredCard(id);\n  }\n}\n\nexport async function showPending(ctx: BotContext) {\n  const list = await attendanceService.pendingForFacilitator(getUser(ctx));\n  if (!list.length) return void ctx.reply('No pending approval requests.');\n  for (const r of list) {\n    await ctx.reply(`✋ <b>Approval request</b>\\n👤 ${esc(r.full_name)} (${esc(r.matric_number)})\\n📚 ${esc(r.code)}\\n🕐 ${fmtTime(r.requested_at)}`,\n      { parse_mode: 'HTML', ...Markup.inlineKeyboard([[Markup.button.callback('✅ Approve', `apr:A:${r.id}`), Markup.button.callback('❌ Reject', `apr:R:${r.id}`)]]) });\n  }\n}\n\nexport async function sendApprovalRequest(telegramId: string, r: { requestId: string; studentName: string; matric: string; courseCode: string; at: Date }) {\n  await sendTelegram(telegramId,\n    `✋ <b>Approval request</b>\\n👤 ${esc(r.studentName)} (${esc(r.matric)})\\n📚 ${esc(r.courseCode)}\\n🕐 ${fmtTime(r.at)}\\n🔎 Verification: Facilitator Approval`,\n    Markup.inlineKeyboard([[Markup.button.callback('✅ Approve', `apr:A:${r.requestId}`), Markup.button.callback('❌ Reject', `apr:R:${r.requestId}`)]]));\n}\n\nexport async function onApproval(ctx: BotContext, decision: 'A' | 'R', requestId: string) {\n  const approve = decision === 'A';\n  const res = await attendanceService.decide(getUser(ctx), requestId, approve);\n  await edit(ctx, `${approve ? '✅ Approved' : '❌ Rejected'}: ${esc(res.student.full_name)} (${esc(res.courseCode)}${approve ? ` – ${res.status}` : ''})`, []);\n  await sendTelegram(res.student.telegram_id, approve\n    ? `✅ <b>Attendance confirmed</b>\\n${esc(res.courseCode)} – ${res.status}`\n    : `❌ Your attendance request for <b>${esc(res.courseCode)}</b> was rejected. You may request again or use another method.`);\n}\n\nexport const _unused = { pool, getSession, counts, assertSessionAccess };\n",
 "src/bot/handlers/home.ts": "import { Markup } from 'telegraf';\nimport { ADMIN_ROLES, Role, Roles } from '../../types';\nimport { card, esc } from '../../utils/format';\nimport { BotContext, getUser } from '../context';\n\nexport interface MenuItem { key: string; label: string }\nconst m = (key: string, label: string): MenuItem => ({ key, label });\n\nconst ADMIN_BASE: MenuItem[] = [\n  m('add_department', '🏛 Add Department'), m('add_course', '📚 Add Course'), m('add_classroom', '📍 Add Classroom'),\n  m('add_facilitator', '👨‍🏫 Authorize Facilitator'), m('assign_course', '🔗 Assign Course'), m('list_courses', '📋 Courses'),\n  m('list_classrooms', '🏫 Classrooms'), m('modify_attendance', '✏️ Modify Attendance'), m('report_course', '📄 Course Report'),\n  m('report_range', '🗓 Date-range Report'), m('list_audit', '🧾 Audit Log'), m('profile', '👤 Profile'),\n];\nconst REPORTS = [m('report_session', '📄 Session CSV'), m('report_course', '📄 Course CSV'), m('report_student', '📄 Student CSV'), m('report_range', '🗓 Date-range CSV')];\n\nexport const MENUS: Record<Role, MenuItem[]> = {\n  [Roles.STUDENT]: [\n    m('dashboard', '📊 Dashboard'), m('checkin', '✅ Check In'), m('my_attendance', '📈 My Attendance'), m('my_courses', '📚 My Courses'),\n    m('history', '🕘 History'), m('notifications', '🔔 Notifications'), m('profile', '👤 Profile'),\n  ],\n  [Roles.FACILITATOR]: [\n    m('new_session', '🟢 New Session'), m('active_session', '📌 Active Session'), m('live', '👥 Live Attendance'), m('pending', '✋ Pending Requests'),\n    m('end_session', '⏹ End Session'), m('modify_attendance', '✏️ Modify Attendance'), ...REPORTS, m('my_courses', '📚 My Courses'), m('profile', '👤 Profile'),\n  ],\n  [Roles.ATTENDANCE_OFFICER]: [m('modify_attendance', '✏️ Modify Attendance'), ...REPORTS, m('profile', '👤 Profile')],\n  [Roles.SUPER_ADMIN]: [...ADMIN_BASE.slice(0, 5), m('add_admin', '🛡 Add Staff Account'), ...ADMIN_BASE.slice(5)],\n  [Roles.SCHOOL_ADMIN]: ADMIN_BASE,\n  [Roles.DEPARTMENT_ADMIN]: ADMIN_BASE,\n};\n\nexport async function showHome(ctx: BotContext) {\n  const user = getUser(ctx);\n  if (!user) {\n    await ctx.reply(card('Welcome', ['Verified Presence. Smarter Attendance. Better Academics.', '', 'Register to get started.']),\n      { parse_mode: 'HTML', ...Markup.inlineKeyboard([[Markup.button.callback('🎓 Register as Student', 'reg:start')]]) });\n    return;\n  }\n  const items = MENUS[user.role] ?? [];\n  const rows = [];\n  for (let i = 0; i < items.length; i += 2) rows.push(items.slice(i, i + 2).map((x) => Markup.button.callback(x.label, `menu:${x.key}`)));\n  const roleLabel = ADMIN_ROLES.includes(user.role) ? 'Administrator' : user.role.charAt(0) + user.role.slice(1).toLowerCase().replace('_', ' ');\n  await ctx.reply(card(`Hello, ${esc(user.full_name)}`, [`Role: ${roleLabel}`, 'Choose an option below.']), { parse_mode: 'HTML', ...Markup.inlineKeyboard(rows) });\n}\n",
 "src/bot/handlers/menu.ts": "import { ADMIN_ROLES, Roles } from '../../types';\nimport { adminService } from '../../services/admin';\nimport { assertRole } from '../../services/authorization';\nimport { classroomService, courseService, facilitatorService, studentService } from '../../services/registry';\nimport { esc } from '../../utils/format';\nimport { fmtDateTime } from '../../utils/time';\nimport { ForbiddenError } from '../../utils/errors';\nimport { BotContext, getUser } from '../context';\nimport { startFlow } from '../flows/engine';\nimport { showActiveSession, showEndConfirm, showLive, showPending } from './facilitator';\nimport { MENUS } from './home';\nimport { sessionService } from '../../services/sessions';\nimport { showCourseBreakdown, showDashboard, showHistory, showNotifications } from './student';\n\nconst FLOW_ACTIONS: Record<string, string> = {\n  add_department: 'addDepartment', add_course: 'addCourse', add_classroom: 'addClassroom', add_facilitator: 'addFacilitator',\n  assign_course: 'assignCourse', add_admin: 'addAdmin', new_session: 'newSession', checkin: 'checkIn',\n  modify_attendance: 'modifyAttendance', report_session: 'reportSession', report_course: 'reportCourse',\n  report_student: 'reportStudent', report_range: 'reportRange',\n};\nconst html = (ctx: BotContext, t: string) => ctx.reply(t, { parse_mode: 'HTML' });\n\nexport async function handleMenu(ctx: BotContext, key: string) {\n  const user = getUser(ctx);\n  // Authorize against the server-side menu for this user's role; never trust callback data alone.\n  if (!user || user.status !== 'ACTIVE' || !MENUS[user.role]?.some((x) => x.key === key)) throw new ForbiddenError();\n\n  if (FLOW_ACTIONS[key]) return startFlow(ctx, FLOW_ACTIONS[key]);\n\n  switch (key) {\n    case 'profile': {\n      if (user.role === Roles.STUDENT) {\n        const p = await studentService.profile(user.id);\n        return html(ctx, `👤 <b>${esc(user.full_name)}</b>\\n🆔 ${esc(p.matric_number)}\\n🏛 ${esc(p.department_name)}\\n🎓 ${p.level} Level`);\n      }\n      if (user.role === Roles.FACILITATOR) {\n        const p = await facilitatorService.profile(user.id);\n        const cs = await courseService.forFacilitator(p.id);\n        return html(ctx, `👤 <b>${esc(user.full_name)}</b>\\n🆔 Staff ID: ${esc(p.staff_id)}\\n🏛 ${esc(p.department_name)}\\n📚 ${cs.length ? cs.map((c) => esc(c.code)).join(', ') : 'No courses assigned'}`);\n      }\n      return html(ctx, `👤 <b>${esc(user.full_name)}</b>\\nRole: ${user.role}`);\n    }\n    case 'my_courses': {\n      let list;\n      if (user.role === Roles.STUDENT) {\n        const p = await studentService.profile(user.id);\n        list = await courseService.forStudent(p.id, p.department_id, p.level);\n      } else {\n        const p = await facilitatorService.profile(user.id);\n        list = await courseService.forFacilitator(p.id);\n      }\n      if (!list.length) return html(ctx, user.role === Roles.STUDENT ? 'No courses found for your department and level yet.' : 'No courses assigned to you yet. Ask an administrator.');\n      return html(ctx, '<b>Your courses</b>\\n\\n' + list.map((c) => `• ${esc(c.code)} – ${esc(c.title)}`).join('\\n'));\n    }\n    case 'list_courses': {\n      assertRole(user, ...ADMIN_ROLES);\n      const list = await courseService.list();\n      return html(ctx, list.length ? '<b>Courses</b>\\n\\n' + list.map((c) => `• ${esc(c.code)} – ${esc(c.title)} (${c.level}L)`).join('\\n') : 'No courses yet.');\n    }\n    case 'list_classrooms': {\n      assertRole(user, ...ADMIN_ROLES);\n      const list = await classroomService.list();\n      return html(ctx, list.length ? '<b>Classrooms</b>\\n\\n' + list.map((r) => `• ${esc(r.name)} – ${esc(r.building)}, floor ${r.floor} (${r.default_radius_m} m)`).join('\\n') : 'No classrooms yet.');\n    }\n    case 'list_audit': {\n      const rows = await adminService.recentAudit(user);\n      return html(ctx, rows.length ? '<b>Recent activity</b>\\n\\n' + rows.map((r) => `${fmtDateTime(r.created_at)} · ${esc(r.action)}${r.actor ? ` · ${esc(r.actor)}` : ''}`).join('\\n') : 'No activity yet.');\n    }\n    case 'dashboard': return showDashboard(ctx);\n    case 'my_attendance': return showCourseBreakdown(ctx);\n    case 'history': return showHistory(ctx, 0);\n    case 'notifications': return showNotifications(ctx);\n    case 'active_session': return showActiveSession(ctx);\n    case 'end_session': return showEndConfirm(ctx);\n    case 'pending': return showPending(ctx);\n    case 'live': {\n      const s = await sessionService.activeForFacilitator(user);\n      if (!s) return html(ctx, 'You have no active session.');\n      return showLive(ctx, s.id, 0);\n    }\n    default: return html(ctx, 'Unknown option.');\n  }\n}\n",
 "src/bot/handlers/student.ts": "import { Markup } from 'telegraf';\nimport { pool } from '../../database/pool';\nimport { students } from '../../repositories';\nimport { HISTORY_PAGE, history, recentNotifications, studentSummary } from '../../services/stats';\nimport { LINE, esc } from '../../utils/format';\nimport { METHOD_LABEL, STATUS_ICON } from '../../utils/status';\nimport { fmtDate, fmtDateTime, fmtTime } from '../../utils/time';\nimport { BotContext, getUser } from '../context';\nimport { edit } from './facilitator';\n\nasync function me(ctx: BotContext) {\n  const st = await students.profileByUserId(pool, getUser(ctx)!.id);\n  return st;\n}\n\nexport async function showDashboard(ctx: BotContext) {\n  const st = await me(ctx);\n  const { overall: o } = await studentSummary(st.id);\n  if (!o.total) return void ctx.reply('No attendance history yet. Your stats appear after your first completed class.');\n  await ctx.reply(`${LINE}\\n📊 <b>My Attendance</b>\\n${LINE}\\n\\n<b>${o.pct}%</b> overall\\n\\n📚 ${o.total} classes\\n🟢 ${o.present} Present\\n🟡 ${o.late} Late\\n🔴 ${o.absent} Absent\\n🔵 ${o.excused} Excused\\n${LINE}`, { parse_mode: 'HTML' });\n}\n\nexport async function showCourseBreakdown(ctx: BotContext) {\n  const st = await me(ctx);\n  const { courses } = await studentSummary(st.id);\n  if (!courses.length) return void ctx.reply('No attendance history yet.');\n  await ctx.reply('<b>By course</b>\\n\\n' + courses.map((c) => `<b>${esc(c.code)}</b> – ${c.pct}%\\n🟢 ${c.present}  🟡 ${c.late}  🔴 ${c.absent}  🔵 ${c.excused}  (of ${c.total})`).join('\\n\\n'), { parse_mode: 'HTML' });\n}\n\nexport async function showHistory(ctx: BotContext, page: number) {\n  const st = await me(ctx);\n  const p = Math.max(0, page);\n  const { rows, total, pages } = await history(st.id, p);\n  if (!total) return void ctx.reply('No attendance history yet.');\n  const body = rows.map((r) => `${STATUS_ICON[r.status] ?? '•'} <b>${esc(r.code)}</b> · ${fmtDate(r.started_at)}\\n   ${r.status}${r.checked_in_at ? ` · ${fmtTime(r.checked_in_at)}` : ''}${r.method ? ` · ${METHOD_LABEL[r.method] ?? r.method}` : ''}`).join('\\n\\n');\n  const nav = [];\n  if (p > 0) nav.push(Markup.button.callback('◀ Newer', `hist:${p - 1}`));\n  if (p < pages - 1) nav.push(Markup.button.callback('Older ▶', `hist:${p + 1}`));\n  await edit(ctx, `<b>History</b> (page ${p + 1}/${pages})\\n\\n${body}`, nav.length ? [nav] : []);\n}\n\nexport async function showNotifications(ctx: BotContext) {\n  const list = await recentNotifications(getUser(ctx)!.id);\n  if (!list.length) return void ctx.reply('🔔 No notifications yet.');\n  await ctx.reply('<b>Notifications</b>\\n\\n' + list.map((n) => `${n.read_at ? '' : '🆕 '}<b>${esc(n.title)}</b>\\n${esc(n.body)}\\n<i>${fmtDateTime(n.created_at)}</i>`).join('\\n\\n'), { parse_mode: 'HTML' });\n}\n\nexport const _p = HISTORY_PAGE;\n",
 "src/bot/index.ts": "import { Telegraf, session } from 'telegraf';\nimport { message } from 'telegraf/filters';\nimport { env } from '../config/env';\nimport { initNotifier } from '../services/notifier';\nimport { BotContext, getUser } from './context';\nimport './flows/definitions';\nimport './flows/operations';\nimport { cancelFlow, onLocation, onPick, onText, startFlow } from './flows/engine';\nimport { onApproval, onSessionAction } from './handlers/facilitator';\nimport { showHome } from './handlers/home';\nimport { handleMenu } from './handlers/menu';\nimport { showHistory } from './handlers/student';\nimport { handleError, loadUser, rateLimit } from './middleware';\n\nconst UUID = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';\n\nexport function createBot() {\n  const bot = new Telegraf<BotContext>(env.TELEGRAM_BOT_TOKEN);\n  initNotifier(bot.telegram);\n  bot.use(session({ defaultSession: () => ({}) }));\n  bot.use(rateLimit);\n  bot.use(loadUser);\n  bot.catch(handleError);\n\n  bot.start(async (ctx) => { ctx.session.flow = undefined; await showHome(ctx); });\n  bot.command('help', (ctx) => ctx.reply('Commands:\\n/start – menu\\n/checkin – check into a class\\n/newsession – start a class session\\n/endsession – end your session\\n/profile – your profile\\n/attendance – your attendance\\n/cancel – cancel current action'));\n  bot.command('cancel', cancelFlow);\n  const shortcuts: Record<string, string> = { profile: 'profile', checkin: 'checkin', newsession: 'new_session', endsession: 'end_session', attendance: 'my_attendance' };\n  for (const [cmd, key] of Object.entries(shortcuts)) {\n    bot.command(cmd, async (ctx) => {\n      ctx.session.flow = undefined;\n      if (!getUser(ctx)) return showHome(ctx);\n      return handleMenu(ctx, key);\n    });\n  }\n\n  bot.action('reg:start', async (ctx) => {\n    await ctx.answerCbQuery();\n    if (getUser(ctx)) return void ctx.reply('You are already registered.');\n    await startFlow(ctx, 'registerStudent');\n  });\n  bot.action(/^menu:([a-z_]{1,30})$/, async (ctx) => { await ctx.answerCbQuery(); await handleMenu(ctx, ctx.match[1]); });\n  bot.action(/^flow:pick:(\\d{1,2})$/, async (ctx) => { await ctx.answerCbQuery(); await onPick(ctx, ctx.match[1]); });\n  bot.action('flow:cancel', async (ctx) => { await ctx.answerCbQuery(); await cancelFlow(ctx); });\n  bot.action(new RegExp(`^ses:(r|l|e|ok|no):(${UUID})(?::(\\\\d{1,4}))?$`), async (ctx) => {\n    await ctx.answerCbQuery();\n    await onSessionAction(ctx, ctx.match[1], ctx.match[2], Number(ctx.match[3] ?? 0));\n  });\n  bot.action(new RegExp(`^apr:(A|R):(${UUID})$`), async (ctx) => { await ctx.answerCbQuery(); await onApproval(ctx, ctx.match[1] as 'A' | 'R', ctx.match[2]); });\n  bot.action(/^hist:(\\d{1,4})$/, async (ctx) => { await ctx.answerCbQuery(); await showHistory(ctx, Number(ctx.match[1])); });\n\n  bot.on(message('location'), async (ctx) => {\n    const m = ctx.message as any;\n    await onLocation(ctx, m.location.latitude, m.location.longitude, Boolean(m.forward_date || m.forward_origin));\n  });\n  bot.on(message('text'), async (ctx) => {\n    if (ctx.message.text.startsWith('/')) return;\n    if (!(await onText(ctx, ctx.message.text))) await showHome(ctx);\n  });\n  return bot;\n}\n",
 "src/bot/middleware/index.ts": "import { pool } from '../../database/pool';\nimport { users } from '../../repositories';\nimport { AppError } from '../../utils/errors';\nimport { logger } from '../../utils/logger';\nimport { BotContext } from '../context';\n\nexport async function loadUser(ctx: BotContext, next: () => Promise<void>) {\n  if (ctx.from) (ctx.state as any).user = await users.findByTelegramId(pool, String(ctx.from.id));\n  return next();\n}\n\nconst hits = new Map<number, number[]>();\nexport async function rateLimit(ctx: BotContext, next: () => Promise<void>) {\n  const id = ctx.from?.id;\n  if (!id) return next();\n  const now = Date.now();\n  const recent = (hits.get(id) ?? []).filter((t) => now - t < 10_000);\n  recent.push(now);\n  hits.set(id, recent);\n  if (recent.length > 15) {\n    if (recent.length === 16) await ctx.reply('⏳ You are going too fast. Please wait a few seconds.').catch(() => undefined);\n    return;\n  }\n  return next();\n}\n\nexport async function handleError(err: unknown, ctx: BotContext) {\n  const e = err as any;\n  let msg = 'Something went wrong on our side. Please try again shortly.';\n  if (err instanceof AppError) msg = err.userMessage;\n  else if (e?.code === '23505') msg = 'That record already exists.';\n  else logger.error({ err: e, updateType: ctx.updateType }, 'Unhandled bot error'); // details server-side only\n  if (ctx.session) ctx.session.flow = undefined;\n  await ctx.reply(`⚠️ ${msg}`).catch(() => undefined);\n}\n",
 "src/config/env.ts": "import 'dotenv/config';\nimport { z } from 'zod';\n\nconst schema = z.object({\n  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),\n  PORT: z.coerce.number().int().default(3000),\n  TELEGRAM_BOT_TOKEN: z.string().min(10, 'TELEGRAM_BOT_TOKEN is required'),\n  DATABASE_URL: z.string().min(1, 'DATABASE_URL is required'),\n  SUPER_ADMIN_TELEGRAM_IDS: z.string().default(''),\n  TIMEZONE: z.string().default('Africa/Lagos'),\n  LOG_LEVEL: z.enum(['fatal', 'error', 'warn', 'info', 'debug', 'trace']).default('info'),\n  DEFAULT_CODE_ROTATION_MINUTES: z.coerce.number().int().min(1).default(5),\n  DEFAULT_RADIUS_METERS: z.coerce.number().int().min(10).max(1000).default(100),\n  ATTENDANCE_ALERT_THRESHOLD: z.coerce.number().min(0).max(100).default(75),\n});\n\nconst parsed = schema.safeParse(process.env);\nif (!parsed.success) {\n  // Print only field names/messages, never values (may contain secrets)\n  console.error('Invalid environment configuration:', parsed.error.flatten().fieldErrors);\n  process.exit(1);\n}\n\nexport const env = parsed.data;\nexport const superAdminIds = env.SUPER_ADMIN_TELEGRAM_IDS.split(',')\n  .map((s) => s.trim())\n  .filter((s) => /^\\d+$/.test(s));\n",
 "src/database/migrate.ts": "import fs from 'fs';\nimport path from 'path';\nimport { pool, withTransaction } from './pool';\nimport { logger } from '../utils/logger';\n\nexport async function runMigrations(): Promise<void> {\n  await pool.query(`CREATE TABLE IF NOT EXISTS schema_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now())`);\n  const dir = path.join(process.cwd(), 'migrations');\n  const files = fs.readdirSync(dir).filter((f) => f.endsWith('.sql')).sort();\n  const done = new Set((await pool.query<{ name: string }>('SELECT name FROM schema_migrations')).rows.map((r) => r.name));\n  for (const file of files) {\n    if (done.has(file)) continue;\n    const sql = fs.readFileSync(path.join(dir, file), 'utf8');\n    await withTransaction(async (c) => {\n      await c.query(sql);\n      await c.query('INSERT INTO schema_migrations(name) VALUES ($1)', [file]);\n    });\n    logger.info({ migration: file }, 'Migration applied');\n  }\n}\n\nif (require.main === module) {\n  runMigrations()\n    .then(() => pool.end())\n    .catch((e) => { logger.error({ err: e }, 'Migration failed'); process.exit(1); });\n}\n",
 "src/database/pool.ts": "import { Pool, PoolClient, QueryResult, QueryResultRow } from 'pg';\nimport { env } from '../config/env';\n\nexport const pool = new Pool({ connectionString: env.DATABASE_URL, max: 10 });\n\nexport interface Db {\n  query<R extends QueryResultRow = any>(text: string, params?: unknown[]): Promise<QueryResult<R>>;\n}\n\nexport async function withTransaction<T>(fn: (client: PoolClient) => Promise<T>): Promise<T> {\n  const client = await pool.connect();\n  try {\n    await client.query('BEGIN');\n    const result = await fn(client);\n    await client.query('COMMIT');\n    return result;\n  } catch (err) {\n    await client.query('ROLLBACK').catch(() => undefined);\n    throw err;\n  } finally {\n    client.release();\n  }\n}\n",
 "src/jobs.ts": "import { refreshStoredCard } from './bot/handlers/cards';\nimport { sessionService } from './services/sessions';\nimport { logger } from './utils/logger';\n\n/** Single-instance scheduler: expiry, code rotation, closing-soon notices. */\nexport function startScheduler(intervalMs = 10_000) {\n  let busy = false;\n  const tick = async () => {\n    if (busy) return;\n    busy = true;\n    try {\n      const expired = await sessionService.expireDue();\n      await sessionService.closingSoon();\n      const rotated = await sessionService.rotateDue();\n      for (const id of new Set([...expired.map((s) => s.id), ...rotated])) await refreshStoredCard(id);\n    } catch (err) { logger.error({ err }, 'Scheduler tick failed'); }\n    finally { busy = false; }\n  };\n  const timer = setInterval(tick, intervalMs);\n  logger.info({ intervalMs }, 'Scheduler started');\n  return () => clearInterval(timer);\n}\n",
 "src/reports/formatters.ts": "import { toCsv } from '../utils/csv';\n\nexport interface ReportTable { columns: string[]; rows: unknown[][] }\nexport interface ReportFormatter { ext: string; mime: string; render(t: ReportTable): Buffer }\n\nexport const csvFormatter: ReportFormatter = { ext: 'csv', mime: 'text/csv', render: (t) => Buffer.from('\\uFEFF' + toCsv(t.columns, t.rows), 'utf8') };\n\n/** Register PDF / Excel formatters here later; report queries need no changes. */\nexport const formatters: Record<string, ReportFormatter> = { csv: csvFormatter };\n",
 "src/repositories/index.ts": "import { Db } from '../database/pool';\nimport { AppUser, Role } from '../types';\n\nexport interface Department { id: string; name: string; code: string; status: string }\nexport interface Classroom { id: string; name: string; building: string; floor: number; latitude: number; longitude: number; default_radius_m: number; status: string }\nexport interface Course { id: string; code: string; title: string; department_id: string; level: number; semester: string; academic_session: string; status: string }\nexport interface FacilitatorRow { id: string; user_id: string; staff_id: string; department_id: string; full_name: string; department_name: string }\n\nexport const departments = {\n  async list(db: Db): Promise<Department[]> {\n    return (await db.query<Department>(`SELECT * FROM departments WHERE status='ACTIVE' ORDER BY name`)).rows;\n  },\n  async findById(db: Db, id: string): Promise<Department | undefined> {\n    return (await db.query<Department>('SELECT * FROM departments WHERE id=$1', [id])).rows[0];\n  },\n  async create(db: Db, name: string, code: string): Promise<Department> {\n    return (await db.query<Department>('INSERT INTO departments(name,code) VALUES ($1,$2) RETURNING *', [name, code])).rows[0];\n  },\n};\n\nexport const users = {\n  async findByTelegramId(db: Db, telegramId: string): Promise<AppUser | undefined> {\n    return (await db.query<AppUser>('SELECT id, telegram_id::text, role, full_name, status FROM users WHERE telegram_id=$1', [telegramId])).rows[0];\n  },\n  async create(db: Db, telegramId: string, role: Role, fullName: string): Promise<AppUser> {\n    return (await db.query<AppUser>(\n      'INSERT INTO users(telegram_id, role, full_name) VALUES ($1,$2,$3) RETURNING id, telegram_id::text, role, full_name, status',\n      [telegramId, role, fullName])).rows[0];\n  },\n};\n\nexport const students = {\n  async findByMatric(db: Db, matric: string) {\n    return (await db.query('SELECT id FROM students WHERE matric_number=$1', [matric])).rows[0];\n  },\n  async create(db: Db, userId: string, matric: string, departmentId: string, level: number) {\n    return (await db.query('INSERT INTO students(user_id, matric_number, department_id, level) VALUES ($1,$2,$3,$4) RETURNING *', [userId, matric, departmentId, level])).rows[0];\n  },\n  async profileByUserId(db: Db, userId: string) {\n    return (await db.query<{ id: string; matric_number: string; level: number; department_name: string; department_id: string }>(\n      `SELECT s.id, s.matric_number, s.level, s.department_id, d.name AS department_name\n         FROM students s JOIN departments d ON d.id=s.department_id WHERE s.user_id=$1`, [userId])).rows[0];\n  },\n};\n\nexport const facilitators = {\n  async findByStaffId(db: Db, staffId: string) {\n    return (await db.query('SELECT id FROM facilitators WHERE staff_id=$1', [staffId])).rows[0];\n  },\n  async create(db: Db, userId: string, staffId: string, departmentId: string, authorizedBy: string) {\n    return (await db.query('INSERT INTO facilitators(user_id, staff_id, department_id, authorized_by) VALUES ($1,$2,$3,$4) RETURNING *', [userId, staffId, departmentId, authorizedBy])).rows[0];\n  },\n  async list(db: Db): Promise<FacilitatorRow[]> {\n    return (await db.query<FacilitatorRow>(\n      `SELECT f.id, f.user_id, f.staff_id, f.department_id, u.full_name, d.name AS department_name\n         FROM facilitators f JOIN users u ON u.id=f.user_id JOIN departments d ON d.id=f.department_id\n        WHERE f.status='ACTIVE' ORDER BY u.full_name`)).rows;\n  },\n  async profileByUserId(db: Db, userId: string) {\n    return (await db.query<{ id: string; staff_id: string; department_name: string }>(\n      `SELECT f.id, f.staff_id, d.name AS department_name FROM facilitators f JOIN departments d ON d.id=f.department_id WHERE f.user_id=$1`, [userId])).rows[0];\n  },\n};\n\nexport const admins = {\n  async upsert(db: Db, userId: string, departmentId: string | null) {\n    await db.query('INSERT INTO admins(user_id, department_id) VALUES ($1,$2) ON CONFLICT (user_id) DO NOTHING', [userId, departmentId]);\n  },\n  async departmentScope(db: Db, userId: string): Promise<string | null> {\n    return (await db.query<{ department_id: string | null }>('SELECT department_id FROM admins WHERE user_id=$1', [userId])).rows[0]?.department_id ?? null;\n  },\n};\n\nexport const courses = {\n  async create(db: Db, c: Omit<Course, 'id' | 'status'>): Promise<Course> {\n    return (await db.query<Course>(\n      `INSERT INTO courses(code,title,department_id,level,semester,academic_session) VALUES ($1,$2,$3,$4,$5,$6) RETURNING *`,\n      [c.code, c.title, c.department_id, c.level, c.semester, c.academic_session])).rows[0];\n  },\n  async findById(db: Db, id: string): Promise<Course | undefined> {\n    return (await db.query<Course>('SELECT * FROM courses WHERE id=$1', [id])).rows[0];\n  },\n  async list(db: Db): Promise<Course[]> {\n    return (await db.query<Course>(`SELECT * FROM courses WHERE status='ACTIVE' ORDER BY code`)).rows;\n  },\n  async listForFacilitator(db: Db, facilitatorId: string): Promise<Course[]> {\n    return (await db.query<Course>(\n      `SELECT c.* FROM courses c JOIN course_facilitators cf ON cf.course_id=c.id\n        WHERE cf.facilitator_id=$1 AND c.status='ACTIVE' ORDER BY c.code`, [facilitatorId])).rows;\n  },\n  async listForStudent(db: Db, studentId: string, departmentId: string, level: number): Promise<Course[]> {\n    return (await db.query<Course>(\n      `SELECT * FROM courses WHERE status='ACTIVE' AND ((department_id=$2 AND level=$3)\n         OR id IN (SELECT course_id FROM enrollments WHERE student_id=$1)) ORDER BY code`,\n      [studentId, departmentId, level])).rows;\n  },\n  async assignFacilitator(db: Db, courseId: string, facilitatorId: string) {\n    await db.query('INSERT INTO course_facilitators(course_id, facilitator_id) VALUES ($1,$2) ON CONFLICT DO NOTHING', [courseId, facilitatorId]);\n  },\n};\n\nexport const classrooms = {\n  async create(db: Db, c: Omit<Classroom, 'id' | 'status'>): Promise<Classroom> {\n    return (await db.query<Classroom>(\n      `INSERT INTO classrooms(name,building,floor,latitude,longitude,default_radius_m) VALUES ($1,$2,$3,$4,$5,$6) RETURNING *`,\n      [c.name, c.building, c.floor, c.latitude, c.longitude, c.default_radius_m])).rows[0];\n  },\n  async list(db: Db): Promise<Classroom[]> {\n    return (await db.query<Classroom>(`SELECT * FROM classrooms WHERE status='ACTIVE' ORDER BY name`)).rows;\n  },\n};\n\nexport const audit = {\n  async log(db: Db, actorUserId: string | null, action: string, entityType: string, entityId: string | null, metadata: Record<string, unknown> = {}) {\n    await db.query('INSERT INTO audit_logs(actor_user_id, action, entity_type, entity_id, metadata) VALUES ($1,$2,$3,$4,$5)',\n      [actorUserId, action, entityType, entityId, JSON.stringify(metadata)]);\n  },\n};\n",
 "src/server.ts": "import { env, superAdminIds } from './config/env';\nimport { createApp } from './app';\nimport { createBot } from './bot';\nimport { pool } from './database/pool';\nimport { runMigrations } from './database/migrate';\nimport { bootstrapSuperAdmins } from './services/registry';\nimport { startScheduler } from './jobs';\nimport { logger } from './utils/logger';\n\nasync function main() {\n  logger.info({ env: env.NODE_ENV }, 'Starting CUN Attend');\n  await runMigrations();\n  await bootstrapSuperAdmins(superAdminIds);\n  const server = createApp().listen(env.PORT, () => logger.info({ port: env.PORT }, 'HTTP server listening'));\n  const bot = createBot();\n  await bot.telegram.deleteWebhook();\n  bot.launch().catch((e) => { logger.error({ err: e }, 'Bot launch failed'); process.exit(1); });\n  logger.info('Telegram bot connected');\n  const stopJobs = startScheduler();\n  const stop = async (sig: string) => { logger.info({ sig }, 'Shutting down'); stopJobs(); bot.stop(sig); server.close(); await pool.end(); process.exit(0); };\n  process.once('SIGINT', () => stop('SIGINT'));\n  process.once('SIGTERM', () => stop('SIGTERM'));\n}\nmain().catch((e) => { logger.error({ err: e }, 'Fatal startup error'); process.exit(1); });\n",
 "src/services/admin.ts": "import { pool, withTransaction } from '../database/pool';\nimport { admins, audit, departments, users } from '../repositories';\nimport { AppUser, Role, Roles } from '../types';\nimport { AppError } from '../utils/errors';\nimport { assertAdmin, assertRole } from './authorization';\n\nexport const adminService = {\n  async createAdmin(actor: AppUser | undefined, input: { telegramId: string; fullName: string; role: Role; departmentId?: string }) {\n    assertRole(actor, Roles.SUPER_ADMIN);\n    const allowed: Role[] = [Roles.SCHOOL_ADMIN, Roles.DEPARTMENT_ADMIN, Roles.ATTENDANCE_OFFICER];\n    if (!allowed.includes(input.role)) throw new AppError('BAD_ROLE', 'Invalid role.');\n    if (input.role === Roles.DEPARTMENT_ADMIN && !input.departmentId) throw new AppError('NO_DEPT', 'Department required for department admins.');\n    return withTransaction(async (c) => {\n      const existing = await users.findByTelegramId(c, input.telegramId);\n      if (existing) throw new AppError('TELEGRAM_IN_USE', `That Telegram ID is already registered as ${existing.role}.`);\n      if (input.departmentId && !(await departments.findById(c, input.departmentId))) throw new AppError('BAD_DEPT', 'Department not found.');\n      const u = await users.create(c, input.telegramId, input.role, input.fullName);\n      if (input.role !== Roles.ATTENDANCE_OFFICER) await admins.upsert(c, u.id, input.role === Roles.DEPARTMENT_ADMIN ? input.departmentId! : null);\n      await audit.log(c, actor.id, 'ADMIN_CREATED', 'user', u.id, { role: input.role });\n      return u;\n    });\n  },\n  async recentAudit(actor: AppUser | undefined, limit = 15) {\n    assertAdmin(actor);\n    return (await pool.query<{ created_at: Date; action: string; entity_type: string; actor: string | null }>(\n      `SELECT a.created_at, a.action, a.entity_type, u.full_name AS actor FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_user_id ORDER BY a.id DESC LIMIT $1`, [limit])).rows;\n  },\n};\n",
 "src/services/attendance.ts": "import { pool, withTransaction } from '../database/pool';\nimport { audit, students } from '../repositories';\nimport { ADMIN_ROLES, AppUser, Roles } from '../types';\nimport { AppError, ForbiddenError, RejectedCheckIn } from '../utils/errors';\nimport { isValidCoords, isWithinRadius } from '../utils/haversine';\nimport { logger } from '../utils/logger';\nimport { METHOD_LABEL, computeStatus } from '../utils/status';\nimport { fmtTime } from '../utils/time';\nimport { assertRole } from './authorization';\nimport { notify } from './notifier';\nimport { SessionDetail, eligibleSql, getSession, assertSessionAccess } from './sessions';\n\nexport type CheckInMethod = 'CLASS_CODE' | 'LOCATION' | 'FACILITATOR_APPROVAL' | 'COMBINED';\nexport interface CheckInInput {\n  sessionId: string; method: CheckInMethod; code?: string;\n  location?: { lat: number; lng: number; forwarded?: boolean };\n}\nexport type CheckInResult =\n  | { kind: 'RECORDED'; status: 'PRESENT' | 'LATE'; method: string; at: Date; courseCode: string; courseTitle: string; distanceM?: number }\n  | { kind: 'PENDING_APPROVAL'; requestId: string; courseCode: string; facilitatorTelegramId: string; studentName: string; matric: string; at: Date };\n\nconst MAX_CODE_FAILS = 5;\n\nexport const attendanceService = {\n  /** Active, eligible sessions the student has not yet been recorded for. */\n  async activeFor(user: AppUser) {\n    assertRole(user, Roles.STUDENT);\n    const st = await students.profileByUserId(pool, user.id);\n    return (await pool.query<{ id: string; code: string; title: string; room: string; methods: string[]; require_combined: boolean }>(\n      `SELECT s.id, c.code, c.title, r.name AS room, s.methods, s.require_combined\n         FROM sessions s JOIN courses c ON c.id=s.course_id JOIN classrooms r ON r.id=s.classroom_id\n        WHERE s.status='ACTIVE' AND s.ends_at > now()\n          AND ((c.department_id=$2 AND c.level=$3) OR EXISTS (SELECT 1 FROM enrollments e WHERE e.course_id=c.id AND e.student_id=$1))\n          AND NOT EXISTS (SELECT 1 FROM attendance a WHERE a.session_id=s.id AND a.student_id=$1 AND a.status <> 'REJECTED')\n        ORDER BY s.started_at DESC`, [st.id, st.department_id, st.level])).rows;\n  },\n\n  async checkIn(user: AppUser | undefined, input: CheckInInput): Promise<CheckInResult> {\n    assertRole(user, Roles.STUDENT);\n    try {\n      const result = await withTransaction(async (c): Promise<CheckInResult> => {\n        const st = await students.profileByUserId(c, user.id);\n        if (!st) throw new ForbiddenError();\n        const s = await getSession(c, input.sessionId, true);\n        const now = new Date();\n        if (!s || s.status !== 'ACTIVE' || s.ends_at <= now) throw new AppError('NOT_ACTIVE', 'That session is no longer active.');\n\n        const elig = await c.query(`SELECT 1 FROM (${eligibleSql(1)}) e WHERE e.student_id=$2`, [s.course_id, st.id]);\n        if (!elig.rowCount) throw new AppError('NOT_ELIGIBLE', 'You are not eligible for this class.');\n\n        const existing = (await c.query<{ id: string; status: string; method: string | null; checked_in_at: Date | null; created_at: Date }>(\n          'SELECT id, status, method, checked_in_at, created_at FROM attendance WHERE session_id=$1 AND student_id=$2', [s.id, st.id])).rows[0];\n        if (existing && existing.status !== 'REJECTED') {\n          throw new AppError('DUPLICATE', `You are already recorded for this class: ${existing.status} at ${fmtTime(existing.checked_in_at ?? existing.created_at)}${existing.method ? ` via ${METHOD_LABEL[existing.method] ?? existing.method}` : ''}.`);\n        }\n\n        // Method must be enabled by the facilitator.\n        const m = input.method;\n        const allowed = m === 'COMBINED'\n          ? s.require_combined && s.methods.includes('CLASS_CODE') && s.methods.includes('LOCATION')\n          : s.methods.includes(m) && (!s.require_combined || m === 'FACILITATOR_APPROVAL');\n        if (!allowed) throw new AppError('METHOD_DISABLED', 'That verification method is not enabled for this class.');\n\n        if (m === 'FACILITATOR_APPROVAL') return requestApproval(c, s, st, user, existing?.id, now);\n\n        if (m === 'CLASS_CODE' || m === 'COMBINED') await verifyCode(c, s, user.id, input.code);\n        let distanceM: number | undefined;\n        if (m === 'LOCATION' || m === 'COMBINED') distanceM = verifyLocation(s, input.location);\n\n        const status = computeStatus(s.started_at, now, s.late_after_minutes);\n        const method = m === 'COMBINED' ? 'CODE_AND_LOCATION' : m;\n        const up = await c.query(\n          `INSERT INTO attendance(session_id, student_id, status, method, checked_in_at, distance_m) VALUES ($1,$2,$3,$4,$5,$6)\n           ON CONFLICT (session_id, student_id) DO UPDATE SET status=EXCLUDED.status, method=EXCLUDED.method, checked_in_at=EXCLUDED.checked_in_at, distance_m=EXCLUDED.distance_m\n             WHERE attendance.status='REJECTED' RETURNING id`, [s.id, st.id, status, method, now, distanceM ?? null]);\n        if (!up.rowCount) throw new AppError('DUPLICATE', 'You are already recorded for this class.');\n        await audit.log(c, user.id, 'CHECKIN_RECORDED', 'attendance', up.rows[0].id, { sessionId: s.id, method, status, distanceM: distanceM !== undefined ? Math.round(distanceM) : undefined });\n        logger.info({ sessionId: s.id, status, method }, 'Attendance recorded');\n        return { kind: 'RECORDED', status, method, at: now, courseCode: s.course_code, courseTitle: s.course_title, distanceM };\n      });\n      if (result.kind === 'RECORDED') {\n        await notify(pool, { userId: user.id, type: 'ATTENDANCE_RECORDED', push: false,\n          title: 'Attendance recorded', body: `${result.courseCode}: ${result.status} at ${fmtTime(result.at)}` });\n      }\n      return result;\n    } catch (e) {\n      if (e instanceof RejectedCheckIn) {\n        // Logged outside the rolled-back transaction: suspicious-activity trail.\n        await audit.log(pool, user.id, e.auditAction, 'session', input.sessionId, e.meta).catch(() => undefined);\n      }\n      if ((e as any)?.code === '23505') throw new AppError('DUPLICATE', 'You are already recorded for this class.');\n      throw e;\n    }\n  },\n\n  /** Only the facilitator who owns the session may decide. */\n  async decide(actor: AppUser | undefined, requestId: string, approve: boolean) {\n    assertRole(actor, Roles.FACILITATOR);\n    return withTransaction(async (c) => {\n      const r = (await c.query<{ id: string; session_id: string; student_id: string; status: string; requested_at: Date }>(\n        'SELECT * FROM attendance_requests WHERE id=$1 FOR UPDATE', [requestId])).rows[0];\n      if (!r) throw new AppError('NO_REQUEST', 'Request not found.');\n      const s = await getSession(c, r.session_id);\n      if (!s || s.facilitator_user_id !== actor.id) throw new ForbiddenError('Only the session facilitator can decide this request.');\n      if (r.status !== 'PENDING') throw new AppError('DECIDED', 'This request was already handled.');\n      if (s.status !== 'ACTIVE' || s.ends_at <= new Date()) throw new AppError('NOT_ACTIVE', 'This session is no longer active.');\n      const status = approve ? computeStatus(s.started_at, r.requested_at, s.late_after_minutes) : 'REJECTED';\n      await c.query(`UPDATE attendance_requests SET status=$2, decided_by=$3, decided_at=now() WHERE id=$1`, [requestId, approve ? 'APPROVED' : 'REJECTED', actor.id]);\n      await c.query(`UPDATE attendance SET status=$3, checked_in_at=$4 WHERE session_id=$1 AND student_id=$2 AND status='PENDING'`,\n        [r.session_id, r.student_id, status, approve ? r.requested_at : null]);\n      await audit.log(c, actor.id, approve ? 'APPROVAL_GRANTED' : 'APPROVAL_REJECTED', 'attendance_request', requestId, { sessionId: s.id, status });\n      const stu = (await c.query<{ user_id: string; telegram_id: string; full_name: string }>(\n        `SELECT u.id AS user_id, u.telegram_id::text AS telegram_id, u.full_name FROM students st JOIN users u ON u.id=st.user_id WHERE st.id=$1`, [r.student_id])).rows[0];\n      return { status, courseCode: s.course_code, student: stu, sessionId: s.id };\n    });\n  },\n\n  async pendingForFacilitator(actor: AppUser | undefined) {\n    assertRole(actor, Roles.FACILITATOR);\n    return (await pool.query<{ id: string; full_name: string; matric_number: string; code: string; requested_at: Date }>(\n      `SELECT ar.id, u.full_name, st.matric_number, c.code, ar.requested_at\n         FROM attendance_requests ar JOIN sessions s ON s.id=ar.session_id JOIN facilitators f ON f.id=s.facilitator_id\n         JOIN students st ON st.id=ar.student_id JOIN users u ON u.id=st.user_id JOIN courses c ON c.id=s.course_id\n        WHERE f.user_id=$1 AND ar.status='PENDING' AND s.status='ACTIVE' ORDER BY ar.requested_at`, [actor.id])).rows;\n  },\n\n  async requestDetails(requestId: string) {\n    return (await pool.query<{ id: string; full_name: string; code: string; requested_at: Date }>(\n      `SELECT ar.id, u.full_name, c.code, ar.requested_at FROM attendance_requests ar JOIN sessions s ON s.id=ar.session_id\n         JOIN students st ON st.id=ar.student_id JOIN users u ON u.id=st.user_id JOIN courses c ON c.id=s.course_id WHERE ar.id=$1`, [requestId])).rows[0];\n  },\n\n  /** Authorized status change. Never silent: previous/new/who/when/why are stored. */\n  async modify(actor: AppUser | undefined, input: { sessionId: string; matric: string; newStatus: string; reason: string }) {\n    assertRole(actor, Roles.FACILITATOR, Roles.ATTENDANCE_OFFICER, ...ADMIN_ROLES);\n    const allowed = ['PRESENT', 'LATE', 'ABSENT', 'EXCUSED'];\n    if (!allowed.includes(input.newStatus)) throw new AppError('BAD_STATUS', 'Invalid status.');\n    const reason = input.reason.trim();\n    if (reason.length < 3) throw new AppError('NO_REASON', 'A reason is required.');\n    return withTransaction(async (c) => {\n      const s = await getSession(c, input.sessionId, true);\n      if (!s) throw new AppError('NO_SESSION', 'Session not found.');\n      await assertSessionAccess(c, actor, s);\n      const row = (await c.query<{ student_id: string; user_id: string; telegram_id: string; full_name: string }>(\n        `SELECT e.student_id, e.user_id, e.telegram_id, e.full_name FROM (${eligibleSql(1)}) e WHERE e.matric_number=$2`, [s.course_id, input.matric.trim().toUpperCase()])).rows[0];\n      if (!row) throw new AppError('NO_STUDENT', 'No eligible student with that matric number in this session.');\n      const prev = (await c.query<{ id: string; status: string }>('SELECT id, status FROM attendance WHERE session_id=$1 AND student_id=$2 FOR UPDATE', [s.id, row.student_id])).rows[0];\n      const previous = prev?.status ?? 'ABSENT';\n      if (previous === input.newStatus) throw new AppError('NO_CHANGE', `Student is already ${previous}.`);\n      const method = prev ? undefined : 'MANUAL';\n      const up = await c.query<{ id: string }>(\n        `INSERT INTO attendance(session_id, student_id, status, method, checked_in_at) VALUES ($1,$2,$3,'MANUAL', CASE WHEN $3 IN ('PRESENT','LATE') THEN now() END)\n         ON CONFLICT (session_id, student_id) DO UPDATE SET status=EXCLUDED.status RETURNING id`, [s.id, row.student_id, input.newStatus]);\n      await c.query('INSERT INTO attendance_changes(attendance_id, previous_status, new_status, changed_by, reason) VALUES ($1,$2,$3,$4,$5)', [up.rows[0].id, previous, input.newStatus, actor.id, reason]);\n      await audit.log(c, actor.id, 'ATTENDANCE_MODIFIED', 'attendance', up.rows[0].id, { previous, newStatus: input.newStatus, reason, createdManual: !!method });\n      await notify(c, { userId: row.user_id, telegramId: row.telegram_id, type: 'ATTENDANCE_MODIFIED', push: true,\n        title: `Attendance updated: ${s.course_code}`, body: `${previous} → ${input.newStatus}. Reason: ${reason}` });\n      return { previous, newStatus: input.newStatus, studentName: row.full_name, courseCode: s.course_code };\n    });\n  },\n};\n\nasync function verifyCode(c: any, s: SessionDetail, userId: string, code?: string) {\n  const fails = Number((await c.query(\n    `SELECT COUNT(*)::int n FROM audit_logs WHERE actor_user_id=$1 AND action='CHECKIN_CODE_FAILED' AND entity_id=$2 AND created_at > now() - interval '5 minutes'`, [userId, s.id])).rows[0].n);\n  if (fails >= MAX_CODE_FAILS) throw new AppError('THROTTLED', 'Too many wrong codes. Please wait a few minutes and try again.');\n  const ok = code && /^\\d{4}$/.test(code) &&\n    (await c.query(`SELECT 1 FROM attendance_codes WHERE session_id=$1 AND code=$2 AND revoked_at IS NULL AND valid_until > now()`, [s.id, code])).rowCount;\n  if (!ok) throw new RejectedCheckIn('That code is incorrect or has expired. Ask your facilitator for the current code.', 'CHECKIN_CODE_FAILED', {});\n}\n\nfunction verifyLocation(s: SessionDetail, loc?: { lat: number; lng: number; forwarded?: boolean }): number {\n  if (!loc || !isValidCoords(loc)) throw new AppError('NO_LOCATION', 'A valid location is required.');\n  if (loc.forwarded) throw new RejectedCheckIn('Forwarded locations are not accepted. Please share your current location.', 'CHECKIN_LOCATION_FORWARDED', {});\n  const { within, distanceM } = isWithinRadius(loc, { lat: s.latitude, lng: s.longitude }, s.radius_m);\n  if (!within) {\n    throw new RejectedCheckIn(`You are outside the permitted radius (about ${Math.round(distanceM)} m away; limit ${s.radius_m} m). Move closer to the classroom and try again.`,\n      'CHECKIN_LOCATION_FAILED', { distanceM: Math.round(distanceM), radius: s.radius_m });\n  }\n  return distanceM;\n}\n\nasync function requestApproval(c: any, s: SessionDetail, st: { id: string }, user: AppUser, existingId: string | undefined, now: Date): Promise<CheckInResult> {\n  if (existingId) await c.query(`UPDATE attendance SET status='PENDING', method='FACILITATOR_APPROVAL', checked_in_at=NULL WHERE id=$1`, [existingId]);\n  else await c.query(`INSERT INTO attendance(session_id, student_id, status, method) VALUES ($1,$2,'PENDING','FACILITATOR_APPROVAL')`, [s.id, st.id]);\n  const req = await c.query('INSERT INTO attendance_requests(session_id, student_id, requested_at) VALUES ($1,$2,$3) RETURNING id', [s.id, st.id, now]);\n  const matric = (await c.query('SELECT matric_number FROM students WHERE id=$1', [st.id])).rows[0].matric_number;\n  await audit.log(c, user.id, 'APPROVAL_REQUESTED', 'attendance_request', req.rows[0].id, { sessionId: s.id });\n  return { kind: 'PENDING_APPROVAL', requestId: req.rows[0].id, courseCode: s.course_code, facilitatorTelegramId: s.facilitator_telegram_id, studentName: user.full_name, matric, at: now };\n}\n",
 "src/services/authorization.ts": "import { Db } from '../database/pool';\nimport { admins } from '../repositories';\nimport { ADMIN_ROLES, AppUser, Role, Roles } from '../types';\nimport { ForbiddenError } from '../utils/errors';\n\n/** Server-side role check. Never rely on Telegram UI to hide buttons. */\nexport function assertRole(user: AppUser | undefined, ...allowed: Role[]): asserts user is AppUser {\n  if (!user || user.status !== 'ACTIVE' || !allowed.includes(user.role)) throw new ForbiddenError();\n}\n\nexport function assertAdmin(user: AppUser | undefined): asserts user is AppUser {\n  assertRole(user, ...ADMIN_ROLES);\n}\n\n/** DEPARTMENT_ADMIN may only act inside their own department. */\nexport async function assertDepartmentScope(db: Db, user: AppUser, departmentId: string): Promise<void> {\n  assertAdmin(user);\n  if (user.role !== Roles.DEPARTMENT_ADMIN) return;\n  const scope = await admins.departmentScope(db, user.id);\n  if (!scope || scope !== departmentId) throw new ForbiddenError('This action is outside your department.');\n}\n",
 "src/services/notifier.ts": "import { Telegram } from 'telegraf';\nimport { Db } from '../database/pool';\nimport { logger } from '../utils/logger';\n\nlet telegram: Telegram | undefined;\nexport const initNotifier = (t: Telegram) => { telegram = t; };\nexport const getTelegram = () => telegram;\nconst sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));\n\nexport async function sendTelegram(telegramId: string, html: string, extra: Record<string, unknown> = {}) {\n  if (!telegram) return;\n  try { await telegram.sendMessage(telegramId, html, { parse_mode: 'HTML', ...extra } as any); }\n  catch (err) { logger.warn({ err: (err as Error).message, telegramId }, 'Telegram send failed'); }\n}\n\n/** Stores a notification (deduplicated by key) and optionally pushes it. Never throws. */\nexport async function notify(db: Db, n: { userId: string; telegramId?: string; type: string; title: string; body: string; dedupeKey?: string; push?: boolean }) {\n  try {\n    const res = await db.query(\n      `INSERT INTO notifications(user_id,type,title,body,dedupe_key) VALUES ($1,$2,$3,$4,$5) ON CONFLICT (dedupe_key) DO NOTHING RETURNING id`,\n      [n.userId, n.type, n.title, n.body, n.dedupeKey ?? null]);\n    if (!res.rowCount || !n.push) return;\n    let tg = n.telegramId;\n    if (!tg) tg = (await db.query<{ telegram_id: string }>('SELECT telegram_id::text FROM users WHERE id=$1', [n.userId])).rows[0]?.telegram_id;\n    if (tg) await sendTelegram(tg, `<b>${n.title}</b>\\n${n.body}`);\n  } catch (err) { logger.error({ err }, 'notify failed'); }\n}\n\n/** Paced broadcast to stay under Telegram rate limits. */\nexport async function broadcast(items: { telegramId: string; html: string }[]) {\n  for (const i of items) { await sendTelegram(i.telegramId, i.html); await sleep(60); }\n}\n",
 "src/services/registry.ts": "import { pool, withTransaction } from '../database/pool';\nimport { admins, audit, classrooms, courses, departments, facilitators, students, users } from '../repositories';\nimport { AppUser, Roles } from '../types';\nimport { AppError } from '../utils/errors';\nimport { logger } from '../utils/logger';\nimport { assertAdmin, assertDepartmentScope } from './authorization';\n\nexport const departmentService = {\n  list: () => departments.list(pool),\n  async create(actor: AppUser | undefined, name: string, code: string) {\n    assertAdmin(actor);\n    if (actor.role === Roles.DEPARTMENT_ADMIN) assertAdmin(undefined); // only school-level admins create departments\n    return withTransaction(async (c) => {\n      const d = await departments.create(c, name, code);\n      await audit.log(c, actor.id, 'DEPARTMENT_CREATED', 'department', d.id, { name, code });\n      return d;\n    });\n  },\n};\n\nexport const studentService = {\n  async register(input: { telegramId: string; fullName: string; matric: string; departmentId: string; level: number }) {\n    return withTransaction(async (c) => {\n      if (await users.findByTelegramId(c, input.telegramId))\n        throw new AppError('ALREADY_REGISTERED', 'This Telegram account is already registered.');\n      if (await students.findByMatric(c, input.matric))\n        throw new AppError('MATRIC_TAKEN', 'That matric number is already registered. Contact administration if this is a mistake.');\n      if (!(await departments.findById(c, input.departmentId)))\n        throw new AppError('BAD_DEPARTMENT', 'Selected department is no longer available.');\n      const user = await users.create(c, input.telegramId, Roles.STUDENT, input.fullName);\n      const student = await students.create(c, user.id, input.matric, input.departmentId, input.level);\n      await audit.log(c, user.id, 'STUDENT_REGISTERED', 'student', student.id, { matric: input.matric });\n      logger.info({ studentId: student.id }, 'Student registered');\n      return user;\n    });\n  },\n  profile: (userId: string) => students.profileByUserId(pool, userId),\n};\n\nexport const facilitatorService = {\n  list: () => facilitators.list(pool),\n  profile: (userId: string) => facilitators.profileByUserId(pool, userId),\n  /** Admin pre-authorizes a Telegram ID; arbitrary users can never self-promote. */\n  async authorize(actor: AppUser | undefined, input: { telegramId: string; fullName: string; staffId: string; departmentId: string }) {\n    assertAdmin(actor);\n    return withTransaction(async (c) => {\n      await assertDepartmentScope(c, actor, input.departmentId);\n      const existing = await users.findByTelegramId(c, input.telegramId);\n      if (existing) throw new AppError('TELEGRAM_IN_USE', `That Telegram ID is already registered as ${existing.role}.`);\n      if (await facilitators.findByStaffId(c, input.staffId)) throw new AppError('STAFF_TAKEN', 'That Staff ID already exists.');\n      const user = await users.create(c, input.telegramId, Roles.FACILITATOR, input.fullName);\n      const f = await facilitators.create(c, user.id, input.staffId, input.departmentId, actor.id);\n      await audit.log(c, actor.id, 'FACILITATOR_AUTHORIZED', 'facilitator', f.id, { staffId: input.staffId });\n      return f;\n    });\n  },\n};\n\nexport const courseService = {\n  list: () => courses.list(pool),\n  forFacilitator: (facilitatorId: string) => courses.listForFacilitator(pool, facilitatorId),\n  forStudent: (studentId: string, deptId: string, level: number) => courses.listForStudent(pool, studentId, deptId, level),\n  async create(actor: AppUser | undefined, input: { code: string; title: string; departmentId: string; level: number; semester: string; session: string }) {\n    assertAdmin(actor);\n    return withTransaction(async (c) => {\n      await assertDepartmentScope(c, actor, input.departmentId);\n      const course = await courses.create(c, {\n        code: input.code, title: input.title, department_id: input.departmentId,\n        level: input.level, semester: input.semester, academic_session: input.session,\n      });\n      await audit.log(c, actor.id, 'COURSE_CREATED', 'course', course.id, { code: input.code });\n      return course;\n    });\n  },\n  async assignFacilitator(actor: AppUser | undefined, courseId: string, facilitatorId: string) {\n    assertAdmin(actor);\n    return withTransaction(async (c) => {\n      const course = await courses.findById(c, courseId);\n      if (!course) throw new AppError('NO_COURSE', 'Course not found.');\n      await assertDepartmentScope(c, actor, course.department_id);\n      await courses.assignFacilitator(c, courseId, facilitatorId);\n      await audit.log(c, actor.id, 'COURSE_FACILITATOR_ASSIGNED', 'course', courseId, { facilitatorId });\n    });\n  },\n};\n\nexport const classroomService = {\n  list: () => classrooms.list(pool),\n  async create(actor: AppUser | undefined, input: { name: string; building: string; floor: number; latitude: number; longitude: number; radius: number }) {\n    assertAdmin(actor);\n    return withTransaction(async (c) => {\n      const room = await classrooms.create(c, { ...input, default_radius_m: input.radius });\n      await audit.log(c, actor.id, 'CLASSROOM_CREATED', 'classroom', room.id, { name: input.name });\n      return room;\n    });\n  },\n};\n\n/** Bootstrap SUPER_ADMINs from env on startup (idempotent). */\nexport async function bootstrapSuperAdmins(ids: string[]) {\n  for (const id of ids) {\n    await withTransaction(async (c) => {\n      let u = await users.findByTelegramId(c, id);\n      if (!u) {\n        u = await users.create(c, id, Roles.SUPER_ADMIN, 'Super Admin');\n        await audit.log(c, null, 'SUPER_ADMIN_BOOTSTRAPPED', 'user', u.id, {});\n      }\n      if (u.role === Roles.SUPER_ADMIN) await admins.upsert(c, u.id, null);\n    });\n  }\n}\n",
 "src/services/reports.ts": "import { env } from '../config/env';\nimport { pool } from '../database/pool';\nimport { admins, audit, facilitators } from '../repositories';\nimport { formatters } from '../reports/formatters';\nimport { ADMIN_ROLES, AppUser, Roles } from '../types';\nimport { AppError, ForbiddenError } from '../utils/errors';\nimport { METHOD_LABEL } from '../utils/status';\nimport { fmtDate, fmtDateTime } from '../utils/time';\nimport { assertRole } from './authorization';\nimport { eligibleSql, getSession, assertSessionAccess } from './sessions';\n\nexport const REPORT_COLUMNS = ['Student ID', 'Student Name', 'Course', 'Date', 'Session ID', 'Check-in Time', 'Verification Method', 'Distance', 'Status'];\n\ntype Add = (v: unknown) => string;\nasync function scopeClause(user: AppUser, add: Add): Promise<string> {\n  if (user.role === Roles.FACILITATOR) {\n    const f = await facilitators.profileByUserId(pool, user.id);\n    return `s.course_id IN (SELECT course_id FROM course_facilitators WHERE facilitator_id=${add(f.id)})`;\n  }\n  if (user.role === Roles.DEPARTMENT_ADMIN) return `c.department_id=${add(await admins.departmentScope(pool, user.id))}`;\n  return '';\n}\n\nconst mapRow = (r: any): unknown[] => [\n  r.matric_number, r.full_name, r.code, fmtDate(r.started_at), r.session_id,\n  r.checked_in_at ? fmtDateTime(r.checked_in_at) : '', r.method ? METHOD_LABEL[r.method] ?? r.method : '',\n  r.distance_m !== null && r.distance_m !== undefined ? Math.round(Number(r.distance_m)) : '', r.status,\n];\n\nconst BASE = `SELECT st.matric_number, u.full_name, c.code, s.started_at, s.id AS session_id, a.checked_in_at, a.method, a.distance_m, a.status\n  FROM attendance a JOIN students st ON st.id=a.student_id JOIN users u ON u.id=st.user_id\n  JOIN sessions s ON s.id=a.session_id JOIN courses c ON c.id=s.course_id`;\n\nexport type ReportKind = 'SESSION' | 'COURSE' | 'STUDENT' | 'RANGE';\n\nexport const reportService = {\n  async generate(actor: AppUser | undefined, kind: ReportKind, args: { sessionId?: string; courseId?: string; matric?: string; from?: string; to?: string }, format = 'csv') {\n    assertRole(actor, Roles.FACILITATOR, Roles.ATTENDANCE_OFFICER, ...ADMIN_ROLES);\n    const fmt = formatters[format];\n    if (!fmt) throw new AppError('BAD_FORMAT', 'Unsupported report format.');\n    let rows: unknown[][];\n    let name: string;\n\n    if (kind === 'SESSION') {\n      const s = await getSession(pool, args.sessionId ?? '');\n      if (!s) throw new AppError('NO_SESSION', 'Session not found.');\n      await assertSessionAccess(pool, actor, s);\n      // Includes eligible students with no record yet as ABSENT (live export).\n      const res = await pool.query(\n        `SELECT e.matric_number, e.full_name, $3::text AS code, $4::timestamptz AS started_at, $1::uuid AS session_id,\n                a.checked_in_at, a.method, a.distance_m, COALESCE(a.status::text,'ABSENT') AS status\n           FROM (${eligibleSql(2)}) e LEFT JOIN attendance a ON a.session_id=$1 AND a.student_id=e.student_id ORDER BY e.full_name`,\n        [s.id, s.course_id, s.course_code, s.started_at]);\n      rows = res.rows.map(mapRow);\n      name = `session_${s.course_code.replace(/\\s+/g, '')}_${fmtDate(s.started_at)}`;\n    } else {\n      const params: unknown[] = [];\n      const add: Add = (v) => { params.push(v); return `$${params.length}`; };\n      const where: string[] = [];\n      const scope = await scopeClause(actor, add);\n      if (scope) where.push(scope);\n      where.push(`s.status IN ('ENDED','EXPIRED','ACTIVE')`);\n      if (kind === 'COURSE') {\n        if (!args.courseId) throw new AppError('NO_COURSE', 'Course required.');\n        where.push(`s.course_id=${add(args.courseId)}`); name = 'course_attendance';\n      } else if (kind === 'STUDENT') {\n        if (!args.matric) throw new AppError('NO_STUDENT', 'Matric number required.');\n        where.push(`st.matric_number=${add(args.matric.trim().toUpperCase())}`); name = `student_${args.matric.replace(/[^A-Za-z0-9]/g, '')}`;\n      } else {\n        if (!args.from || !args.to || !/^\\d{4}-\\d{2}-\\d{2}$/.test(args.from) || !/^\\d{4}-\\d{2}-\\d{2}$/.test(args.to)) throw new AppError('BAD_RANGE', 'Dates must be YYYY-MM-DD.');\n        where.push(`(s.started_at AT TIME ZONE ${add(env.TIMEZONE)})::date BETWEEN ${add(args.from)}::date AND ${add(args.to)}::date`);\n        name = `attendance_${args.from}_to_${args.to}`;\n      }\n      rows = (await pool.query(`${BASE} WHERE ${where.join(' AND ')} ORDER BY s.started_at, u.full_name`, params)).rows.map(mapRow);\n    }\n    await audit.log(pool, actor.id, 'REPORT_GENERATED', 'report', null, { kind, rows: rows.length, format });\n    return { filename: `${name}.${fmt.ext}`, content: fmt.render({ columns: REPORT_COLUMNS, rows }), rowCount: rows.length };\n  },\n};\n\nexport const _forbid = ForbiddenError;\n",
 "src/services/sessions.ts": "import { env } from '../config/env';\nimport { Db, pool, withTransaction } from '../database/pool';\nimport { admins, audit, facilitators } from '../repositories';\nimport { ADMIN_ROLES, AppUser, Roles } from '../types';\nimport { generateCode } from '../utils/code';\nimport { AppError } from '../utils/errors';\nimport { logger } from '../utils/logger';\nimport { attendancePercent } from '../utils/status';\nimport { assertRole } from './authorization';\nimport { notify } from './notifier';\n\nexport interface SessionRow {\n  id: string; course_id: string; facilitator_id: string; classroom_id: string;\n  status: 'ACTIVE' | 'EXPIRED' | 'ENDED' | 'CANCELLED'; methods: string[]; radius_m: number;\n  late_after_minutes: number; duration_minutes: number; code_rotation_minutes: number;\n  latitude: number; longitude: number; started_at: Date; ends_at: Date; ended_at: Date | null;\n  require_combined: boolean; card_chat_id: string | null; card_message_id: string | null;\n}\nexport interface SessionDetail extends SessionRow {\n  course_code: string; course_title: string; course_department_id: string;\n  room_name: string; facilitator_name: string; facilitator_user_id: string; facilitator_telegram_id: string;\n}\n\n/** Eligible students for a course. $p is the placeholder index of the course id. */\nexport const eligibleSql = (p: number) => `\n  SELECT st.id AS student_id, st.user_id, st.matric_number, u.full_name, u.telegram_id::text AS telegram_id\n    FROM students st JOIN users u ON u.id = st.user_id JOIN courses c ON c.id = $${p}\n   WHERE u.status = 'ACTIVE' AND ((st.department_id = c.department_id AND st.level = c.level)\n      OR st.id IN (SELECT student_id FROM enrollments WHERE course_id = c.id))`;\n\nconst DETAIL_SQL = `\n  SELECT s.*, c.code AS course_code, c.title AS course_title, c.department_id AS course_department_id,\n         r.name AS room_name, u.full_name AS facilitator_name, u.id AS facilitator_user_id, u.telegram_id::text AS facilitator_telegram_id\n    FROM sessions s JOIN courses c ON c.id = s.course_id JOIN classrooms r ON r.id = s.classroom_id\n    JOIN facilitators f ON f.id = s.facilitator_id JOIN users u ON u.id = f.user_id`;\n\nexport async function getSession(db: Db, id: string, lock = false): Promise<SessionDetail | undefined> {\n  return (await db.query<SessionDetail>(`${DETAIL_SQL} WHERE s.id = $1 ${lock ? 'FOR UPDATE OF s' : ''}`, [id])).rows[0];\n}\n\n/** Facilitators may only touch their own sessions; admins/officers any (department admins: own department). */\nexport async function assertSessionAccess(db: Db, actor: AppUser | undefined, s: SessionDetail, opts: { ownerOnly?: boolean } = {}) {\n  assertRole(actor, Roles.FACILITATOR, Roles.SUPER_ADMIN, Roles.SCHOOL_ADMIN, Roles.DEPARTMENT_ADMIN, Roles.ATTENDANCE_OFFICER);\n  if (actor.role === Roles.FACILITATOR) {\n    if (s.facilitator_user_id !== actor.id) throw new AppError('NOT_OWNER', 'This session belongs to another facilitator.');\n  } else if (opts.ownerOnly) {\n    throw new AppError('NOT_OWNER', 'Only the session facilitator can do that.');\n  } else if (actor.role === Roles.DEPARTMENT_ADMIN) {\n    const scope = await admins.departmentScope(db, actor.id);\n    if (scope !== s.course_department_id) throw new AppError('OUT_OF_SCOPE', 'This session is outside your department.');\n  }\n}\n\nasync function issueCode(db: Db, sessionId: string, rotationMinutes: number, endsAt: Date): Promise<string> {\n  await db.query('UPDATE attendance_codes SET revoked_at = now() WHERE session_id=$1 AND revoked_at IS NULL', [sessionId]);\n  const prev = (await db.query<{ code: string }>('SELECT code FROM attendance_codes WHERE session_id=$1 ORDER BY valid_from DESC LIMIT 1', [sessionId])).rows[0]?.code;\n  const code = generateCode(prev?.trim());\n  const validUntil = new Date(Math.min(Date.now() + rotationMinutes * 60_000, endsAt.getTime()));\n  await db.query('INSERT INTO attendance_codes(session_id, code, valid_until) VALUES ($1,$2,$3)', [sessionId, code, validUntil]);\n  return code;\n}\n\nexport async function currentCode(db: Db, sessionId: string): Promise<{ code: string; valid_until: Date } | undefined> {\n  return (await db.query<{ code: string; valid_until: Date }>(\n    `SELECT code, valid_until FROM attendance_codes WHERE session_id=$1 AND revoked_at IS NULL AND valid_until > now() ORDER BY valid_from DESC LIMIT 1`, [sessionId])).rows[0];\n}\n\nexport interface Counts { present: number; late: number; pending: number; excused: number; absent: number; eligible: number; notRecorded: number }\nexport async function counts(db: Db, s: Pick<SessionRow, 'id' | 'course_id'>): Promise<Counts> {\n  const r = (await db.query(\n    `SELECT COUNT(*) FILTER (WHERE status='PRESENT')::int present, COUNT(*) FILTER (WHERE status='LATE')::int late,\n            COUNT(*) FILTER (WHERE status='PENDING')::int pending, COUNT(*) FILTER (WHERE status='EXCUSED')::int excused,\n            COUNT(*) FILTER (WHERE status='ABSENT')::int absent\n       FROM attendance WHERE session_id=$1`, [s.id])).rows[0];\n  const eligible = Number((await db.query(`SELECT COUNT(*)::int n FROM (${eligibleSql(1)}) e`, [s.course_id])).rows[0].n);\n  const notRecorded = Math.max(0, eligible - r.present - r.late - r.pending - r.excused - r.absent);\n  return { present: r.present, late: r.late, pending: r.pending, excused: r.excused, absent: r.absent + notRecorded, eligible, notRecorded };\n}\n\nexport const sessionService = {\n  get: (id: string) => getSession(pool, id),\n\n  async activeForFacilitator(user: AppUser): Promise<SessionDetail | undefined> {\n    assertRole(user, Roles.FACILITATOR);\n    return (await pool.query<SessionDetail>(\n      `${DETAIL_SQL} WHERE u.id=$1 AND s.status IN ('ACTIVE','EXPIRED') ORDER BY s.started_at DESC LIMIT 1`, [user.id])).rows[0];\n  },\n\n  async recentForActor(actor: AppUser, limit = 8): Promise<SessionDetail[]> {\n    assertRole(actor, Roles.FACILITATOR, Roles.SUPER_ADMIN, Roles.SCHOOL_ADMIN, Roles.DEPARTMENT_ADMIN, Roles.ATTENDANCE_OFFICER);\n    const params: unknown[] = [limit];\n    let where = '';\n    if (actor.role === Roles.FACILITATOR) { params.push(actor.id); where = 'WHERE u.id = $2'; }\n    else if (actor.role === Roles.DEPARTMENT_ADMIN) { params.push(await admins.departmentScope(pool, actor.id)); where = 'WHERE c.department_id = $2'; }\n    return (await pool.query<SessionDetail>(`${DETAIL_SQL} ${where} ORDER BY s.started_at DESC LIMIT $1`, params)).rows;\n  },\n\n  async coursesForFacilitator(user: AppUser) {\n    assertRole(user, Roles.FACILITATOR);\n    const f = await facilitators.profileByUserId(pool, user.id);\n    return (await pool.query<{ id: string; code: string; title: string }>(\n      `SELECT c.id, c.code, c.title FROM courses c JOIN course_facilitators cf ON cf.course_id=c.id WHERE cf.facilitator_id=$1 AND c.status='ACTIVE' ORDER BY c.code`, [f.id])).rows;\n  },\n\n  async create(actor: AppUser | undefined, input: {\n    courseId: string; classroomId: string; methods: string[]; requireCombined: boolean;\n    radius: number; lateMinutes: number; durationMinutes: number; rotationMinutes?: number;\n  }): Promise<{ session: SessionDetail; code: string | null }> {\n    assertRole(actor, Roles.FACILITATOR);\n    const methods = [...new Set(input.methods)];\n    const valid = ['CLASS_CODE', 'LOCATION', 'FACILITATOR_APPROVAL'];\n    if (!methods.length || methods.some((m) => !valid.includes(m))) throw new AppError('BAD_METHODS', 'Choose at least one valid verification method.');\n    try {\n      const sessionId = await withTransaction(async (c) => {\n        const f = await facilitators.profileByUserId(c, actor.id);\n        if (!f) throw new AppError('NOT_FACILITATOR', 'Facilitator profile not found.');\n        const assigned = await c.query('SELECT 1 FROM course_facilitators WHERE course_id=$1 AND facilitator_id=$2', [input.courseId, f.id]);\n        if (!assigned.rowCount) throw new AppError('NOT_ASSIGNED', 'You are not assigned to that course.');\n        const room = (await c.query<{ latitude: number; longitude: number }>(`SELECT latitude, longitude FROM classrooms WHERE id=$1 AND status='ACTIVE'`, [input.classroomId])).rows[0];\n        if (!room) throw new AppError('NO_ROOM', 'That classroom is not available.');\n        const course = (await c.query(`SELECT 1 FROM courses WHERE id=$1 AND status='ACTIVE'`, [input.courseId])).rowCount;\n        if (!course) throw new AppError('NO_COURSE', 'That course is not active.');\n        const rotation = input.rotationMinutes ?? env.DEFAULT_CODE_ROTATION_MINUTES;\n        const endsAt = new Date(Date.now() + input.durationMinutes * 60_000);\n        const ins = await c.query<{ id: string }>(\n          `INSERT INTO sessions(course_id,facilitator_id,classroom_id,methods,require_combined,radius_m,late_after_minutes,duration_minutes,code_rotation_minutes,latitude,longitude,ends_at)\n           VALUES ($1,$2,$3,$4::verification_method[],$5,$6,$7,$8,$9,$10,$11,$12) RETURNING id`,\n          [input.courseId, f.id, input.classroomId, methods, input.requireCombined, input.radius, input.lateMinutes, input.durationMinutes, rotation, room.latitude, room.longitude, endsAt]);\n        const id = ins.rows[0].id;\n        if (methods.includes('CLASS_CODE')) await issueCode(c, id, rotation, endsAt);\n        await audit.log(c, actor.id, 'SESSION_CREATED', 'session', id, { courseId: input.courseId, methods });\n        await audit.log(c, actor.id, 'SESSION_STARTED', 'session', id, { endsAt });\n        return id;\n      });\n      logger.info({ sessionId }, 'Session started');\n      const session = (await getSession(pool, sessionId))!;\n      const cc = methods.includes('CLASS_CODE') ? (await currentCode(pool, sessionId))?.code ?? null : null;\n      return { session, code: cc };\n    } catch (e: any) {\n      if (e?.code === '23505') throw new AppError('ALREADY_ACTIVE', 'You (or this course) already has an active session. End it first with /endsession.');\n      throw e;\n    }\n  },\n\n  async saveCard(sessionId: string, chatId: number | string, messageId: number | string) {\n    await pool.query('UPDATE sessions SET card_chat_id=$2, card_message_id=$3 WHERE id=$1', [sessionId, chatId, messageId]);\n  },\n\n  async summary(actor: AppUser | undefined, sessionId: string) {\n    const s = await getSession(pool, sessionId);\n    if (!s) throw new AppError('NO_SESSION', 'Session not found.');\n    await assertSessionAccess(pool, actor, s);\n    return { session: s, counts: await counts(pool, s), code: s.status === 'ACTIVE' ? await currentCode(pool, s.id) : undefined };\n  },\n\n  /** Ends a session: unresolved requests -> ABSENT, eligible students with no record -> ABSENT. */\n  async end(actor: AppUser | undefined, sessionId: string) {\n    const result = await withTransaction(async (c) => {\n      const s = await getSession(c, sessionId, true);\n      if (!s) throw new AppError('NO_SESSION', 'Session not found.');\n      await assertSessionAccess(c, actor, s, { ownerOnly: true });\n      if (s.status !== 'ACTIVE' && s.status !== 'EXPIRED') throw new AppError('ALREADY_ENDED', 'This session has already ended.');\n      await c.query(\n        `WITH old AS (SELECT id, status FROM attendance WHERE session_id=$1 AND status IN ('PENDING','REJECTED') FOR UPDATE),\n              upd AS (UPDATE attendance a SET status='ABSENT' FROM old WHERE a.id=old.id RETURNING a.id)\n         INSERT INTO attendance_changes(attendance_id, previous_status, new_status, changed_by, reason)\n         SELECT old.id, old.status, 'ABSENT', $2, 'Unresolved at session end' FROM old`, [sessionId, actor!.id]);\n      await c.query(`UPDATE attendance_requests SET status='EXPIRED' WHERE session_id=$1 AND status='PENDING'`, [sessionId]);\n      await c.query(`INSERT INTO attendance(session_id, student_id, status) SELECT $1, e.student_id, 'ABSENT' FROM (${eligibleSql(2)}) e ON CONFLICT (session_id, student_id) DO NOTHING`, [sessionId, s.course_id]);\n      await c.query(`UPDATE sessions SET status='ENDED', ended_at=now() WHERE id=$1`, [sessionId]);\n      await c.query('UPDATE attendance_codes SET revoked_at=now() WHERE session_id=$1 AND revoked_at IS NULL', [sessionId]);\n      const cnt = await counts(c, s);\n      await audit.log(c, actor!.id, 'SESSION_ENDED', 'session', sessionId, { ...cnt });\n      return { session: s, counts: cnt };\n    });\n    void lowAttendanceAlerts(result.session).catch((err) => logger.error({ err }, 'low attendance alerts failed'));\n    return result;\n  },\n\n  /** Marks overdue ACTIVE sessions EXPIRED and notifies their facilitators. */\n  async expireDue(): Promise<SessionDetail[]> {\n    const ids = (await pool.query<{ id: string }>(\n      `UPDATE sessions SET status='EXPIRED' WHERE status='ACTIVE' AND ends_at <= now() RETURNING id`)).rows;\n    const out: SessionDetail[] = [];\n    for (const { id } of ids) {\n      await pool.query('UPDATE attendance_codes SET revoked_at=now() WHERE session_id=$1 AND revoked_at IS NULL', [id]);\n      await audit.log(pool, null, 'SESSION_EXPIRED', 'session', id, {});\n      const s = await getSession(pool, id);\n      if (s) {\n        out.push(s);\n        await notify(pool, { userId: s.facilitator_user_id, telegramId: s.facilitator_telegram_id, type: 'SESSION_EXPIRED', dedupeKey: `expired:${id}`, push: true,\n          title: `⏰ ${s.course_code} session expired`, body: 'No new check-ins are accepted. Use /endsession to finalize attendance.' });\n      }\n    }\n    return out;\n  },\n\n  async closingSoon() {\n    const rows = (await pool.query<{ id: string }>(\n      `SELECT id FROM sessions WHERE status='ACTIVE' AND ends_at > now() AND ends_at <= now() + interval '5 minutes'`)).rows;\n    for (const { id } of rows) {\n      const s = await getSession(pool, id);\n      if (s) await notify(pool, { userId: s.facilitator_user_id, telegramId: s.facilitator_telegram_id, type: 'SESSION_CLOSING', dedupeKey: `closing:${id}`, push: true,\n        title: `⏳ ${s.course_code} closes in under 5 minutes`, body: 'Late check-ins will stop when the timer runs out.' });\n    }\n  },\n\n  /** Rotates codes whose validity elapsed. Old codes are revoked immediately. Returns rotated session ids. */\n  async rotateDue(): Promise<string[]> {\n    const due = (await pool.query<{ id: string; code_rotation_minutes: number; ends_at: Date }>(\n      `SELECT s.id, s.code_rotation_minutes, s.ends_at FROM sessions s\n        WHERE s.status='ACTIVE' AND s.ends_at > now() AND 'CLASS_CODE' = ANY(s.methods)\n          AND NOT EXISTS (SELECT 1 FROM attendance_codes ac WHERE ac.session_id=s.id AND ac.revoked_at IS NULL AND ac.valid_until > now())`)).rows;\n    for (const s of due) {\n      await withTransaction(async (c) => {\n        await issueCode(c, s.id, s.code_rotation_minutes, s.ends_at);\n        await audit.log(c, null, 'CODE_ROTATED', 'session', s.id, {});\n      });\n    }\n    return due.map((d) => d.id);\n  },\n};\n\n/** Notify students whose course attendance has dropped below the configured threshold (once per session). */\nasync function lowAttendanceAlerts(s: SessionDetail) {\n  const rows = (await pool.query<{ user_id: string; telegram_id: string; total: number; attended: number; excused: number }>(\n    `SELECT st.user_id, u.telegram_id::text AS telegram_id, COUNT(*)::int total,\n            COUNT(*) FILTER (WHERE a.status IN ('PRESENT','LATE'))::int attended, COUNT(*) FILTER (WHERE a.status='EXCUSED')::int excused\n       FROM attendance a JOIN sessions x ON x.id=a.session_id JOIN students st ON st.id=a.student_id JOIN users u ON u.id=st.user_id\n      WHERE x.course_id=$1 AND x.status='ENDED' GROUP BY st.user_id, u.telegram_id`, [s.course_id])).rows;\n  for (const r of rows) {\n    const pct = attendancePercent(r.attended, 0, r.total, r.excused);\n    if (r.total >= 3 && pct < env.ATTENDANCE_ALERT_THRESHOLD) {\n      await notify(pool, { userId: r.user_id, telegramId: r.telegram_id, type: 'LOW_ATTENDANCE', push: true,\n        dedupeKey: `low:${r.user_id}:${s.id}`, title: `⚠️ Low attendance in ${s.course_code}`,\n        body: `Your attendance is ${pct}% (below ${env.ATTENDANCE_ALERT_THRESHOLD}%). Please attend upcoming classes.` });\n    }\n  }\n}\n\nexport const _admin = ADMIN_ROLES;\n",
 "src/services/stats.ts": "import { pool } from '../database/pool';\nimport { attendancePercent } from '../utils/status';\nimport { eligibleSql } from './sessions';\n\nexport interface CourseStat { code: string; title: string; total: number; present: number; late: number; absent: number; excused: number; pct: number }\n\nexport async function studentSummary(studentId: string) {\n  const rows = (await pool.query<{ code: string; title: string; total: number; present: number; late: number; absent: number; excused: number }>(\n    `SELECT c.code, c.title, COUNT(*)::int total,\n            COUNT(*) FILTER (WHERE a.status='PRESENT')::int present, COUNT(*) FILTER (WHERE a.status='LATE')::int late,\n            COUNT(*) FILTER (WHERE a.status='ABSENT')::int absent, COUNT(*) FILTER (WHERE a.status='EXCUSED')::int excused\n       FROM attendance a JOIN sessions s ON s.id=a.session_id JOIN courses c ON c.id=s.course_id\n      WHERE a.student_id=$1 AND s.status='ENDED' GROUP BY c.code, c.title ORDER BY c.code`, [studentId])).rows;\n  const courses: CourseStat[] = rows.map((r) => ({ ...r, pct: attendancePercent(r.present, r.late, r.total, r.excused) }));\n  const sum = (k: keyof CourseStat) => courses.reduce((a, c) => a + (c[k] as number), 0);\n  const overall = { total: sum('total'), present: sum('present'), late: sum('late'), absent: sum('absent'), excused: sum('excused'), pct: 0 };\n  overall.pct = attendancePercent(overall.present, overall.late, overall.total, overall.excused);\n  return { overall, courses };\n}\n\nexport const HISTORY_PAGE = 5;\nexport async function history(studentId: string, page: number) {\n  const total = Number((await pool.query('SELECT COUNT(*)::int n FROM attendance a JOIN sessions s ON s.id=a.session_id WHERE a.student_id=$1 AND s.status=\\'ENDED\\'', [studentId])).rows[0].n);\n  const rows = (await pool.query<{ started_at: Date; code: string; status: string; checked_in_at: Date | null; method: string | null }>(\n    `SELECT s.started_at, c.code, a.status, a.checked_in_at, a.method FROM attendance a JOIN sessions s ON s.id=a.session_id JOIN courses c ON c.id=s.course_id\n      WHERE a.student_id=$1 AND s.status='ENDED' ORDER BY s.started_at DESC LIMIT $2 OFFSET $3`, [studentId, HISTORY_PAGE, page * HISTORY_PAGE])).rows;\n  return { rows, total, pages: Math.max(1, Math.ceil(total / HISTORY_PAGE)) };\n}\n\nexport const LIVE_PAGE = 10;\nexport async function liveList(sessionId: string, courseId: string, page: number) {\n  const q = `SELECT e.full_name, e.matric_number, COALESCE(a.status::text,'ABSENT') AS status\n               FROM (${eligibleSql(2)}) e LEFT JOIN attendance a ON a.session_id=$1 AND a.student_id=e.student_id`;\n  const total = Number((await pool.query(`SELECT COUNT(*)::int n FROM (${q}) x`, [sessionId, courseId])).rows[0].n);\n  const rows = (await pool.query<{ full_name: string; matric_number: string; status: string }>(\n    `${q} ORDER BY CASE COALESCE(a.status::text,'ABSENT') WHEN 'PENDING' THEN 0 WHEN 'PRESENT' THEN 1 WHEN 'LATE' THEN 2 WHEN 'EXCUSED' THEN 3 ELSE 4 END, e.full_name LIMIT $3 OFFSET $4`,\n    [sessionId, courseId, LIVE_PAGE, page * LIVE_PAGE])).rows;\n  return { rows, total, pages: Math.max(1, Math.ceil(total / LIVE_PAGE)) };\n}\n\nexport async function recentNotifications(userId: string, limit = 10) {\n  const rows = (await pool.query<{ title: string; body: string; created_at: Date; read_at: Date | null }>(\n    'SELECT title, body, created_at, read_at FROM notifications WHERE user_id=$1 ORDER BY created_at DESC LIMIT $2', [userId, limit])).rows;\n  await pool.query('UPDATE notifications SET read_at=now() WHERE user_id=$1 AND read_at IS NULL', [userId]);\n  return rows;\n}\n",
 "src/types/index.ts": "export const Roles = {\n  SUPER_ADMIN: 'SUPER_ADMIN',\n  SCHOOL_ADMIN: 'SCHOOL_ADMIN',\n  DEPARTMENT_ADMIN: 'DEPARTMENT_ADMIN',\n  FACILITATOR: 'FACILITATOR',\n  STUDENT: 'STUDENT',\n  ATTENDANCE_OFFICER: 'ATTENDANCE_OFFICER',\n} as const;\nexport type Role = (typeof Roles)[keyof typeof Roles];\nexport const ADMIN_ROLES: Role[] = [Roles.SUPER_ADMIN, Roles.SCHOOL_ADMIN, Roles.DEPARTMENT_ADMIN];\n\nexport interface AppUser {\n  id: string;\n  telegram_id: string; // pg returns bigint as string\n  role: Role;\n  full_name: string;\n  status: 'ACTIVE' | 'INACTIVE' | 'SUSPENDED';\n}\n",
 "src/utils/code.ts": "import { randomInt } from 'crypto';\n\n/** Cryptographically secure 4-digit code, guaranteed different from `previous`. */\nexport function generateCode(previous?: string): string {\n  let code: string;\n  do code = String(randomInt(0, 10000)).padStart(4, '0');\n  while (code === previous);\n  return code;\n}\n",
 "src/utils/csv.ts": "/** CSV with formula-injection protection (cells starting with = + - @ are prefixed with '). */\nexport function csvCell(v: unknown): string {\n  let s = v === null || v === undefined ? '' : String(v);\n  if (/^[=+\\-@\\t\\r]/.test(s)) s = `'${s}`;\n  return /[\",\\n\\r]/.test(s) ? `\"${s.replace(/\"/g, '\"\"')}\"` : s;\n}\nexport function toCsv(columns: string[], rows: unknown[][]): string {\n  return [columns, ...rows].map((r) => r.map(csvCell).join(',')).join('\\r\\n') + '\\r\\n';\n}\n",
 "src/utils/errors.ts": "export class AppError extends Error {\n  constructor(public code: string, public userMessage: string) {\n    super(userMessage);\n  }\n}\nexport class ForbiddenError extends AppError {\n  constructor(msg = 'You do not have permission to do that.') {\n    super('FORBIDDEN', msg);\n  }\n}\n\n/** A failed verification attempt. Thrown inside a transaction; the caller logs it as suspicious activity AFTER rollback. */\nexport class RejectedCheckIn extends AppError {\n  constructor(msg: string, public auditAction: string, public meta: Record<string, unknown> = {}) {\n    super('CHECKIN_REJECTED', msg);\n  }\n}\n",
 "src/utils/format.ts": "export const LINE = '━━━━━━━━━━━━━━━━━━━━';\nexport const esc = (s: unknown): string =>\n  String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');\n\nexport function card(title: string, lines: string[]): string {\n  return [LINE, `🎓 <b>CUN ATTEND</b>`, LINE, '', `<b>${title}</b>`, '', ...lines, '', LINE].join('\\n');\n}\n",
 "src/utils/haversine.ts": "export interface Coords { lat: number; lng: number }\nconst EARTH_RADIUS_M = 6_371_000;\nconst rad = (d: number) => (d * Math.PI) / 180;\n\nexport function isValidCoords(c: Coords): boolean {\n  return Number.isFinite(c.lat) && Number.isFinite(c.lng) && Math.abs(c.lat) <= 90 && Math.abs(c.lng) <= 180;\n}\n\n/** Great-circle distance in metres (Haversine formula). */\nexport function haversineMeters(a: Coords, b: Coords): number {\n  if (!isValidCoords(a) || !isValidCoords(b)) throw new Error('Invalid coordinates');\n  const dLat = rad(b.lat - a.lat);\n  const dLng = rad(b.lng - a.lng);\n  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLng / 2) ** 2;\n  return 2 * EARTH_RADIUS_M * Math.asin(Math.min(1, Math.sqrt(h)));\n}\n\nexport function isWithinRadius(a: Coords, b: Coords, radiusM: number): { within: boolean; distanceM: number } {\n  const distanceM = haversineMeters(a, b);\n  return { within: distanceM <= radiusM, distanceM };\n}\n",
 "src/utils/logger.ts": "import pino from 'pino';\n\nexport const logger = pino({\n  level: process.env.LOG_LEVEL ?? 'info',\n  redact: { paths: ['token', 'password', '*.token', '*.password', 'TELEGRAM_BOT_TOKEN', 'DATABASE_URL'], censor: '[redacted]' },\n  base: { app: 'cun-attend' },\n});\n",
 "src/utils/status.ts": "export type Timely = 'PRESENT' | 'LATE';\n\n/** Class starts at `startedAt`; arriving more than `lateAfterMinutes` later is LATE. */\nexport function computeStatus(startedAt: Date, at: Date, lateAfterMinutes: number): Timely {\n  return at.getTime() - startedAt.getTime() > lateAfterMinutes * 60_000 ? 'LATE' : 'PRESENT';\n}\n\n/** Attendance % = (present + late) / (total - excused). Returns 0 when nothing counts. */\nexport function attendancePercent(present: number, late: number, total: number, excused = 0): number {\n  const denom = total - excused;\n  return denom <= 0 ? 0 : Math.round(((present + late) / denom) * 1000) / 10;\n}\n\nexport const METHOD_LABEL: Record<string, string> = {\n  CLASS_CODE: 'Class Code', LOCATION: 'Location', FACILITATOR_APPROVAL: 'Facilitator Approval',\n  CODE_AND_LOCATION: 'Code + Location', MANUAL: 'Manual',\n};\nexport const STATUS_ICON: Record<string, string> = {\n  PRESENT: '🟢', LATE: '🟡', ABSENT: '🔴', EXCUSED: '🔵', PENDING: '⏳', REJECTED: '⛔',\n};\n",
 "src/utils/time.ts": "import { env } from '../config/env';\n\nconst tf = new Intl.DateTimeFormat('en-NG', { hour: 'numeric', minute: '2-digit', hour12: true, timeZone: env.TIMEZONE });\nconst df = new Intl.DateTimeFormat('en-CA', { year: 'numeric', month: '2-digit', day: '2-digit', timeZone: env.TIMEZONE });\nexport const fmtTime = (d: Date | string) => tf.format(new Date(d)).toUpperCase();\nexport const fmtDate = (d: Date | string) => df.format(new Date(d));\nexport const fmtDateTime = (d: Date | string) => `${fmtDate(d)} ${fmtTime(d)}`;\n",
 "tests/authorization.test.ts": "import { describe, expect, it } from 'vitest';\nimport { assertAdmin, assertRole } from '../src/services/authorization';\nimport { AppUser } from '../src/types';\n\nconst u = (role: AppUser['role'], status: AppUser['status'] = 'ACTIVE'): AppUser => ({ id: '1', telegram_id: '1', role, full_name: 'T', status });\n\ndescribe('role checks', () => {\n  it('blocks unregistered users', () => expect(() => assertAdmin(undefined)).toThrow());\n  it('blocks students from admin actions', () => expect(() => assertAdmin(u('STUDENT'))).toThrow());\n  it('blocks facilitators from admin actions', () => expect(() => assertAdmin(u('FACILITATOR'))).toThrow());\n  it('allows admins', () => expect(() => assertAdmin(u('SCHOOL_ADMIN'))).not.toThrow());\n  it('blocks suspended users', () => expect(() => assertRole(u('SUPER_ADMIN', 'SUSPENDED'), 'SUPER_ADMIN')).toThrow());\n});\n",
 "tests/haversine.test.ts": "import { describe, expect, it } from 'vitest';\nimport { haversineMeters, isWithinRadius } from '../src/utils/haversine';\n\ndescribe('haversine', () => {\n  const a = { lat: 6.5, lng: 3.3 };\n  it('is zero for identical points', () => expect(haversineMeters(a, a)).toBe(0));\n  it('1 degree latitude ≈ 111.2 km', () => expect(haversineMeters({ lat: 0, lng: 0 }, { lat: 1, lng: 0 })).toBeCloseTo(111195, -2));\n  it('is symmetric', () => {\n    const b = { lat: 6.51, lng: 3.31 };\n    expect(haversineMeters(a, b)).toBeCloseTo(haversineMeters(b, a), 6);\n  });\n  it('0.0009° north ≈ 100 m', () => expect(haversineMeters(a, { lat: 6.5009, lng: 3.3 })).toBeCloseTo(100.07, 0));\n  it('accepts within radius, rejects outside', () => {\n    expect(isWithinRadius(a, { lat: 6.5005, lng: 3.3 }, 100).within).toBe(true);\n    expect(isWithinRadius(a, { lat: 6.5020, lng: 3.3 }, 100).within).toBe(false);\n  });\n  it('rejects invalid coordinates', () => expect(() => haversineMeters(a, { lat: 120, lng: 0 })).toThrow());\n});\n",
 "tests/integration.test.ts": "/**\n * Full-flow tests against a real PostgreSQL. Skipped unless TEST_DATABASE_URL is set.\n *   TEST_DATABASE_URL=postgres://... npm test\n */\nimport { afterAll, beforeAll, describe, expect, it } from 'vitest';\n\nconst URL = process.env.TEST_DATABASE_URL;\nconst d = describe.skipIf(!URL);\n\nd('CUN Attend – end-to-end rules', () => {\n  let S: any; let pool: any; let ids: any = {};\n  const users: Record<string, any> = {};\n  const near = { lat: 6.5, lng: 3.3 };\n\n  beforeAll(async () => {\n    process.env.DATABASE_URL = URL!; process.env.TELEGRAM_BOT_TOKEN = 'test-token-0000000000';\n    const db = await import('../src/database/pool'); pool = db.pool;\n    await pool.query('DROP SCHEMA public CASCADE; CREATE SCHEMA public;');\n    await (await import('../src/database/migrate')).runMigrations();\n    S = {\n      reg: await import('../src/services/registry'), sess: await import('../src/services/sessions'),\n      att: await import('../src/services/attendance'), rep: await import('../src/services/reports'),\n      repo: await import('../src/repositories'),\n    };\n    const { Roles } = await import('../src/types');\n    const admin = await S.repo.users.create(pool, '1001', Roles.SUPER_ADMIN, 'Admin');\n    await S.repo.admins.upsert(pool, admin.id, null);\n    users.admin = admin;\n    ids.dept = (await S.reg.departmentService.create(admin, 'Computer Science', 'CSC')).id;\n    ids.room = (await S.reg.classroomService.create(admin, { name: 'ICT Lab 1', building: 'ICT', floor: 0, latitude: near.lat, longitude: near.lng, radius: 100 })).id;\n    ids.course = (await S.reg.courseService.create(admin, { code: 'CSC 405', title: 'Computer Networks', departmentId: ids.dept, level: 400, semester: 'FIRST', session: '2025/2026' })).id;\n    const f = await S.reg.facilitatorService.authorize(admin, { telegramId: '2001', fullName: 'Dr Doe', staffId: 'STF1', departmentId: ids.dept });\n    users.fac = await S.repo.users.findByTelegramId(pool, '2001');\n    await S.reg.courseService.assignFacilitator(admin, ids.course, f.id);\n    for (const [k, tg, matric] of [['a', '3001', 'CSC/001'], ['b', '3002', 'CSC/002'], ['c', '3003', 'CSC/003'], ['d', '3004', 'CSC/004']]) {\n      users[k] = await S.reg.studentService.register({ telegramId: tg, fullName: `Student ${k}`, matric, departmentId: ids.dept, level: 400 });\n    }\n  });\n  afterAll(async () => { await pool?.end(); });\n\n  it('rejects duplicate Telegram accounts and matric numbers', async () => {\n    await expect(S.reg.studentService.register({ telegramId: '3001', fullName: 'X Y Z', matric: 'NEW/1', departmentId: ids.dept, level: 400 })).rejects.toThrow();\n    await expect(S.reg.studentService.register({ telegramId: '9999', fullName: 'X Y Z', matric: 'CSC/001', departmentId: ids.dept, level: 400 })).rejects.toThrow();\n  });\n  it('only admins can authorize facilitators', async () => {\n    await expect(S.reg.facilitatorService.authorize(users.a, { telegramId: '2002', fullName: 'Bad', staffId: 'STF9', departmentId: ids.dept })).rejects.toThrow();\n  });\n  it('only assigned facilitators can start sessions', async () => {\n    await expect(S.sess.sessionService.create(users.a, { courseId: ids.course, classroomId: ids.room, methods: ['CLASS_CODE'], requireCombined: false, radius: 100, lateMinutes: 15, durationMinutes: 60 })).rejects.toThrow();\n  });\n\n  let session: any; let code: string;\n  it('creates a session with a 4-digit code', async () => {\n    const r = await S.sess.sessionService.create(users.fac, { courseId: ids.course, classroomId: ids.room, methods: ['CLASS_CODE', 'LOCATION', 'FACILITATOR_APPROVAL'], requireCombined: false, radius: 100, lateMinutes: 15, durationMinutes: 60 });\n    session = r.session; code = r.code!;\n    expect(code).toMatch(/^\\d{4}$/);\n  });\n  it('blocks a second active session', async () => {\n    await expect(S.sess.sessionService.create(users.fac, { courseId: ids.course, classroomId: ids.room, methods: ['CLASS_CODE'], requireCombined: false, radius: 100, lateMinutes: 15, durationMinutes: 60 })).rejects.toThrow();\n  });\n  it('rejects a wrong code and logs suspicious activity', async () => {\n    const wrong = code === '0000' ? '1111' : '0000';\n    await expect(S.att.attendanceService.checkIn(users.a, { sessionId: session.id, method: 'CLASS_CODE', code: wrong })).rejects.toThrow();\n    const n = (await pool.query(`SELECT COUNT(*)::int n FROM audit_logs WHERE action='CHECKIN_CODE_FAILED'`)).rows[0].n;\n    expect(n).toBeGreaterThan(0);\n  });\n  it('records PRESENT with the right code and blocks duplicates', async () => {\n    const r = await S.att.attendanceService.checkIn(users.a, { sessionId: session.id, method: 'CLASS_CODE', code });\n    expect(r.status).toBe('PRESENT');\n    await expect(S.att.attendanceService.checkIn(users.a, { sessionId: session.id, method: 'CLASS_CODE', code })).rejects.toThrow(/already/i);\n  });\n  it('rotation invalidates the old code immediately', async () => {\n    await pool.query(`UPDATE attendance_codes SET valid_until = now() - interval '1 second' WHERE session_id=$1`, [session.id]);\n    await S.sess.sessionService.rotateDue();\n    await expect(S.att.attendanceService.checkIn(users.b, { sessionId: session.id, method: 'CLASS_CODE', code })).rejects.toThrow();\n    const fresh = await S.sess.currentCode(pool, session.id);\n    expect(fresh.code).not.toBe(code);\n  });\n  it('location: accepts inside radius, rejects outside', async () => {\n    const ok = await S.att.attendanceService.checkIn(users.b, { sessionId: session.id, method: 'LOCATION', location: { lat: 6.5004, lng: 3.3 } });\n    expect(ok.distanceM).toBeLessThan(100);\n    await expect(S.att.attendanceService.checkIn(users.c, { sessionId: session.id, method: 'LOCATION', location: { lat: 6.51, lng: 3.3 } })).rejects.toThrow(/radius/i);\n  });\n  it('late attendance after threshold', async () => {\n    await pool.query(`UPDATE sessions SET started_at = now() - interval '30 minutes' WHERE id=$1`, [session.id]);\n    const r = await S.att.attendanceService.checkIn(users.c, { sessionId: session.id, method: 'LOCATION', location: near });\n    expect(r.status).toBe('LATE');\n  });\n  it('manual approval: only the owning facilitator may decide; rejection works', async () => {\n    const req = await S.att.attendanceService.checkIn(users.d, { sessionId: session.id, method: 'FACILITATOR_APPROVAL' });\n    expect(req.kind).toBe('PENDING_APPROVAL');\n    await expect(S.att.attendanceService.decide(users.a, req.requestId, true)).rejects.toThrow();\n    const res = await S.att.attendanceService.decide(users.fac, req.requestId, false);\n    expect(res.status).toBe('REJECTED');\n    const again = await S.att.attendanceService.checkIn(users.d, { sessionId: session.id, method: 'FACILITATOR_APPROVAL' });\n    const ok = await S.att.attendanceService.decide(users.fac, again.requestId, true);\n    expect(['PRESENT', 'LATE']).toContain(ok.status);\n  });\n  it('modification is logged with previous/new/who/reason', async () => {\n    await S.att.attendanceService.modify(users.fac, { sessionId: session.id, matric: 'CSC/001', newStatus: 'EXCUSED', reason: 'Medical note' });\n    const row = (await pool.query('SELECT * FROM attendance_changes ORDER BY changed_at DESC LIMIT 1')).rows[0];\n    expect(row.previous_status).toBe('PRESENT'); expect(row.new_status).toBe('EXCUSED'); expect(row.reason).toBe('Medical note');\n    await expect(S.att.attendanceService.modify(users.a, { sessionId: session.id, matric: 'CSC/001', newStatus: 'PRESENT', reason: 'cheat' })).rejects.toThrow();\n  });\n  it('expired sessions reject check-ins', async () => {\n    await pool.query(`UPDATE sessions SET ends_at = now() - interval '1 minute' WHERE id=$1`, [session.id]);\n    expect((await S.sess.sessionService.expireDue()).length).toBe(1);\n    await expect(S.att.attendanceService.checkIn(users.a, { sessionId: session.id, method: 'CLASS_CODE', code })).rejects.toThrow();\n  });\n  it('ending the session marks missing students ABSENT and exports CSV', async () => {\n    await S.reg.studentService.register({ telegramId: '3005', fullName: 'Late Joiner', matric: 'CSC/005', departmentId: ids.dept, level: 400 });\n    const { counts } = await S.sess.sessionService.end(users.fac, session.id);\n    expect(counts.absent).toBeGreaterThanOrEqual(1);\n    const rep = await S.rep.reportService.generate(users.fac, 'SESSION', { sessionId: session.id });\n    expect(rep.content.toString()).toContain('Student ID,Student Name,Course,Date,Session ID,Check-in Time,Verification Method,Distance,Status');\n    await expect(S.sess.sessionService.end(users.fac, session.id)).rejects.toThrow();\n  });\n});\n",
 "tests/units.test.ts": "import { describe, expect, it } from 'vitest';\nimport { generateCode } from '../src/utils/code';\nimport { toCsv, csvCell } from '../src/utils/csv';\nimport { attendancePercent, computeStatus } from '../src/utils/status';\n\ndescribe('code generation', () => {\n  it('is always 4 digits', () => { for (let i = 0; i < 500; i++) expect(generateCode()).toMatch(/^\\d{4}$/); });\n  it('never repeats the previous code', () => { for (let i = 0; i < 500; i++) expect(generateCode('1234')).not.toBe('1234'); });\n});\n\ndescribe('late threshold (class 10:00, late after 15 min)', () => {\n  const start = new Date('2026-01-01T10:00:00Z');\n  it('10:08 is PRESENT', () => expect(computeStatus(start, new Date('2026-01-01T10:08:00Z'), 15)).toBe('PRESENT'));\n  it('10:15 exactly is PRESENT', () => expect(computeStatus(start, new Date('2026-01-01T10:15:00Z'), 15)).toBe('PRESENT'));\n  it('10:22 is LATE', () => expect(computeStatus(start, new Date('2026-01-01T10:22:00Z'), 15)).toBe('LATE'));\n});\n\ndescribe('attendance percentage', () => {\n  it('counts present and late, ignores excused', () => expect(attendancePercent(6, 2, 11, 1)).toBe(80));\n  it('is 0 with no classes', () => expect(attendancePercent(0, 0, 0)).toBe(0));\n});\n\ndescribe('csv', () => {\n  it('quotes commas and quotes', () => expect(csvCell('a,\"b\"')).toBe('\"a,\"\"b\"\"\"'));\n  it('neutralises formula injection', () => expect(csvCell('=HYPERLINK(\"x\")')).toMatch(/^\"?'=/));\n  it('builds rows', () => expect(toCsv(['A', 'B'], [[1, 'x']])).toBe('A,B\\r\\n1,x\\r\\n'));\n});\n",
 "tsconfig.json": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2022\",\n    \"module\": \"node16\",\n    \"moduleResolution\": \"node16\",\n    \"outDir\": \"dist\",\n    \"rootDir\": \"src\",\n    \"strict\": true,\n    \"esModuleInterop\": true,\n    \"skipLibCheck\": true,\n    \"resolveJsonModule\": true,\n    \"forceConsistentCasingInFileNames\": true\n  },\n  \"include\": [\"src\"]\n}\n"
};
let n = 0;
for (const [p, c] of Object.entries(files)) {
  fs.mkdirSync(path.dirname(p) || '.', { recursive: true });
  fs.writeFileSync(p, c);
  n++;
}
console.log('CUN Attend: wrote ' + n + ' files');
